  }

  updateTitle(dt) {
    this.camera.x = damp(this.camera.x, START.x + 120 + Math.sin(this.time * .08) * 24, 1.4, dt);
    this.camera.y = damp(this.camera.y, START.y - 250 + Math.sin(this.time * .11) * 18, 1.4, dt);
    this.camera.zoom = damp(this.camera.zoom, this.camera.baseZoom * .97, 1.4, dt);
