  releaseHook(silent = false) {
    const h = this.hook;
    this.reeling = false;
    if (h.state === 'attached' || h.state === 'flying') {
      if (!silent) this.toast('');
      const hand = this.hand();
      h.state = 'retracting';
      h.t = 0;
      h.dur = .18;
      h.anchor = null;
