  addParticle(o) {
    this.particles.push(o);
  }

  spawnDust(pos, type, speed) {
    const color = type === 'sand' ? 'rgba(214,186,132,.5)'
      : type === 'moss' ? 'rgba(116,146,84,.5)'
        : type === 'stone' ? 'rgba(170,168,150,.42)'
          : 'rgba(150,120,82,.5)';
    for (let i = 0; i < 3; i++) {
      this.addParticle({
        x: pos.x + (Math.random() - .5) * 10,
