/* ══════════════════════════════════════════════════════════════
   PAINT — shared drawing helpers and palettes
   ══════════════════════════════════════════════════════════════ */

export const TAU = Math.PI * 2;
export const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
export const lerp = (a, b, t) => a + (b - a) * t;

export function hashStr(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}

export function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function rgb(hex) {
  const n = parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

export function mix(a, b, t) {
  const A = rgb(a), B = rgb(b);
  return `rgb(${Math.round(lerp(A[0], B[0], t))},${Math.round(lerp(A[1], B[1], t))},${Math.round(lerp(A[2], B[2], t))})`;
}

export function withA(color, a) {
  if (color.startsWith('#')) {
    const [r, g, b] = rgb(color);
    return `rgba(${r},${g},${b},${a})`;
  }
  if (color.startsWith('rgb(')) return color.replace('rgb(', 'rgba(').replace(')', `,${a})`);
  return color;
}

export function rr(ctx, x, y, w, h, r) {
  const rad = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
  ctx.beginPath();
  ctx.moveTo(x + rad, y);
  ctx.lineTo(x + w - rad, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
  ctx.lineTo(x + w, y + h - rad);
  ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
  ctx.lineTo(x + rad, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
  ctx.lineTo(x, y + rad);
  ctx.quadraticCurveTo(x, y, x + rad, y);
  ctx.closePath();
}

export function ellipse(ctx, x, y, rx, ry, rot = 0) {
  ctx.beginPath();
  ctx.ellipse(x, y, Math.max(.01, rx), Math.max(.01, ry), rot, 0, TAU);
}

export function poly(ctx, pts, close = true) {
  ctx.beginPath();
  ctx.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
  if (close) ctx.closePath();
}

export function vgrad(ctx, x0, y0, x1, y1, stops) {
  const g = ctx.createLinearGradient(x0, y0, x1, y1);
  for (const [p, c] of stops) g.addColorStop(p, c);
  return g;
}

export const SKY = {
  low: { top: '#173d4b', mid: '#2e6870', low: '#86a58e', hor: '#e9b471', under: '#b98252' },
  mid: { top: '#0e2b3e', mid: '#225160', low: '#80948b', hor: '#c3a67a', under: '#8a6f52' },
  high: { top: '#050d19', mid: '#0a1f33', low: '#25374a', hor: '#6c5f61', under: '#3a3039' },
};

export const TYPE_STYLE = {
  sand: { base: '#a9834f', top: '#e3c58a', edge: '#f2dbaa', dark: '#6e502e', texture: '#7a5a33' },
  wood: { base: '#5d3d22', top: '#8d6038', edge: '#b3814d', dark: '#33200f', texture: '#3e2814' },
  deck: { base: '#67452a', top: '#94673c', edge: '#bd8b55', dark: '#3a2616', texture: '#442c19' },
  rock: { base: '#565248', top: '#7a7362', edge: '#948c78', dark: '#34322b', texture: '#403e36' },
  moss: { base: '#4d5c3e', top: '#7f9a5b', edge: '#a4b97a', dark: '#2c3724', texture: '#38452c' },
  stone: { base: '#6d6a5d', top: '#938e7a', edge: '#aca68f', dark: '#45433a', texture: '#514e43' },
  gold: { base: '#6f5b32', top: '#c9a34e', edge: '#f4d488', dark: '#3f2f17', texture: '#5d4a27' },
};

/** Add a soft rounded shadow beneath an object. */
export function shadowBlob(ctx, x, y, rx, ry, alpha = .3) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, rx);
  g.addColorStop(0, `rgba(4,8,8,${alpha})`);
  g.addColorStop(.65, `rgba(4,8,8,${alpha * .55})`);
  g.addColorStop(1, 'rgba(4,8,8,0)');
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(1, ry / rx);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, rx, 0, TAU);
  ctx.fill();
  ctx.restore();
}

/** A wobbly organic polygon from a center, radius and seed. */
export function blob(ctx, x, y, rx, ry, rand, points = 9, jag = .18) {
  const pts = [];
  for (let i = 0; i < points; i++) {
    const a = (i / points) * TAU;
    const j = 1 + (rand() - .5) * jag * 2;
    pts.push({ x: x + Math.cos(a) * rx * j, y: y + Math.sin(a) * ry * j });
  }
  ctx.beginPath();
  ctx.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < pts.length; i++) {
    const p = pts[i], n = pts[(i + 1) % pts.length];
    ctx.quadraticCurveTo(p.x, p.y, (p.x + n.x) / 2, (p.y + n.y) / 2);
  }
  ctx.closePath();
  return pts;
}

/* ══════════════════════════════════════════════════════════════
   TERRAIN — island mass, cliff shadows, ledges and their grain
   ══════════════════════════════════════════════════════════════ */

import {
  TAU, clamp, lerp, hashStr, mulberry32, rr, poly,
  TYPE_STYLE, withA,
} from './paint.js';

export function preparePlatforms(level) {
  for (const p of level.platforms) {
    const rand = mulberry32(hashStr(p.id + p.type));
    const L = p.len, T = p.t;
    const tex = { specks: [], cracks: [], tufts: [], seams: [], nails: [], joints: [], veins: [] };
    const n = Math.min(42, Math.max(14, Math.floor(L / 12)));
    for (let i = 0; i < n; i++) {
      tex.specks.push({ x: (rand() - .5) * L, y: (rand() - .5) * T, r: .6 + rand() * 1.9, a: .1 + rand() * .3 });
    }
    const cracks = Math.min(7, Math.max(2, Math.floor(L / 65)));
    for (let i = 0; i < cracks; i++) {
      const x = (rand() - .5) * L * .86;
      const y = (rand() - .5) * T * .5;
      const seg = [{ x, y }];
      let cx = x, cy = y;
      for (let j = 0; j < 3; j++) {
        cx += (rand() - .5) * T * .8;
        cy += (rand() - .3) * T * .5;
        seg.push({ x: cx, y: cy });
      }
      tex.cracks.push(seg);
    }
    const tufts = Math.max(3, Math.floor(L / 30));
    for (let i = 0; i < tufts; i++) {
      tex.tufts.push({ x: (rand() - .5) * L * .94, h: 3 + rand() * 9, lean: (rand() - .5) * 5 });
    }
    const seams = Math.max(2, Math.floor(L / 58));
    for (let i = 0; i < seams; i++) tex.seams.push((rand() - .5) * L * .9);
    for (let i = 0; i < Math.max(4, Math.floor(L / 46)); i++) {
      tex.nails.push({ x: (rand() - .5) * L * .92, y: (rand() - .5) * T * .4, o: rand() });
    }
    const joints = Math.max(2, Math.floor(L / 70));
    for (let i = 0; i < joints; i++) tex.joints.push((rand() - .5) * L);
    for (let i = 0; i < Math.max(3, Math.floor(L / 55)); i++) {
      tex.veins.push({ x0: (rand() - .5) * L, x1: (rand() - .5) * L, y: (rand() - .5) * T * .6, w: .5 + rand() * 1.5 });
    }
    p.tex = tex;
    p.seed = rand();
  }
}

/** A big, soft, impossible island silhouette behind everything. */
export function drawIslandBackdrop(ctx, game, time) {
  if (!game._island) {
    const rand = mulberry32(99181);
    const pts = [];
    for (let y = 520; y >= -10520; y -= 260) {
      const k = (520 - y) / 11040;
      const cx = 170 * Math.sin(y / 1180) + 120 * Math.sin(y / 430 + 1.2) + 120;
      const w = 760 + 230 * Math.sin(y / 840 + .6) + 120 * Math.sin(y / 330) + lerp(120, -80, k);
      pts.push({
        y,
        left: cx - w / 2 + (rand() - .5) * 90,
        right: cx + w / 2 + (rand() - .5) * 90,
        cx,
      });
    }
    game._island = pts;
  }
  const pts = game._island;
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(pts[0].left, pts[0].y);
  for (let i = 1; i < pts.length; i++) {
    const a = pts[i - 1], b = pts[i];
    ctx.quadraticCurveTo(a.left, (a.y + b.y) / 2, (a.left + b.left) / 2, (a.y + b.y) / 2);
  }
  for (let i = pts.length - 1; i >= 0; i--) {
    const b = pts[i];
    const a = pts[Math.max(0, i - 1)];
    if (i === pts.length - 1) ctx.lineTo(b.right, b.y);
    else ctx.quadraticCurveTo(b.right, (a.y + b.y) / 2, (b.right + a.right) / 2, (a.y + b.y) / 2);
  }
  ctx.closePath();

  const g = ctx.createLinearGradient(0, 500, 0, -10600);
  g.addColorStop(0, '#3b2f21');
  g.addColorStop(.15, '#2a3025');
  g.addColorStop(.35, '#23352b');
  g.addColorStop(.55, '#252f2c');
  g.addColorStop(.78, '#2b2d2b');
  g.addColorStop(1, '#24282c');
  ctx.fillStyle = g;
  ctx.fill();

  // faint strata
  ctx.save();
  ctx.clip();
  const rand = mulberry32(4242);
  for (let i = 0; i < 46; i++) {
    const y = lerp(400, -10400, i / 46);
    ctx.strokeStyle = `rgba(180,170,140,${.012 + rand() * .02})`;
    ctx.lineWidth = 2 + rand() * 9;
    ctx.beginPath();
    ctx.moveTo(-1200, y);
    ctx.bezierCurveTo(-300, y + 40, 400, y - 50, 1300, y + 10);
    ctx.stroke();
  }
  ctx.restore();

  // atmospheric haze in the middle
  const hz = ctx.createLinearGradient(0, -2000, 0, -9000);
  hz.addColorStop(0, 'rgba(120,150,145,0)');
  hz.addColorStop(.5, 'rgba(110,140,140,.055)');
  hz.addColorStop(1, 'rgba(80,110,120,.12)');
  ctx.fillStyle = hz;
  ctx.fill();
  ctx.restore();
}

export function drawUndercliffs(ctx, game, cam, time) {
  for (const p of game.level.platforms) {
    if (p.ship) continue;
    const depth = p.type === 'sand' && p.id === 'beach' ? 520 : 90 + p.seed * 150;
    const rand = mulberry32(hashStr(p.id + 'cliff'));
    const nx = p.nx, ny = p.ny;
    const base = {
      sand: '#54402a', wood: '#392718', deck: '#3a2717', rock: '#2d2b25',
      moss: '#2b3423', stone: '#33322d', gold: '#3b3120',
    }[p.type] || '#2e2b25';
    const x1 = p.x1, y1 = p.y1, x2 = p.x2, y2 = p.y2;
    const d1 = depth * (.62 + rand() * .55);
    const d2 = depth * (.62 + rand() * .55);
    const midx = (x1 + x2) / 2 + nx * depth * .28 + (rand() - .5) * 60;
    const midy = (y1 + y2) / 2 + ny * depth * .28 + (rand() - .5) * 30;
    const pts = [
      { x: x1, y: y1 + 4 },
      { x: x2, y: y2 + 4 },
      { x: x2 + nx * d2 + (rand() - .5) * 40, y: y2 + ny * d2 },
      { x: midx + nx * depth * .4, y: midy + ny * depth * .45 },
      { x: x1 + nx * d1 + (rand() - .5) * 40, y: y1 + ny * d1 },
    ];
    poly(ctx, pts);
    ctx.fillStyle = base;
    ctx.fill();
    // underside shade
    ctx.save();
    ctx.clip();
    const g = ctx.createLinearGradient(0, (y1 + y2) / 2, 0, (y1 + y2) / 2 + ny * depth);
    g.addColorStop(0, 'rgba(0,0,0,0)');
    g.addColorStop(1, 'rgba(0,0,0,.42)');
    ctx.fillStyle = g;
    ctx.fillRect(p.cx - p.len / 2 - 200, Math.min(y1, y2) - 20, p.len + 400, depth + 500);
    ctx.restore();
    // hanging roots / vines from the underside
    if ((p.type === 'moss' || p.type === 'jungle') && p.len > 100) {
      const r2 = mulberry32(hashStr(p.id + 'roots'));
      for (let i = 0; i < 4; i++) {
        const rx = p.x1 + r2() * (p.x2 - p.x1);
        const len = 30 + r2() * 150;
        ctx.strokeStyle = 'rgba(58,75,45,.7)';
        ctx.lineWidth = 1.4;
        ctx.beginPath();
        ctx.moveTo(rx, p.y1 + 2);
        ctx.bezierCurveTo(rx + 8, p.y1 + len * .4, rx - 9, p.y1 + len * .7, rx + 4, p.y1 + len);
        ctx.stroke();
      }
    }
  }
}

function drawBase(ctx, p) {
  const st = TYPE_STYLE[p.type] || TYPE_STYLE.rock;
  const L = p.len, T = p.t;
  const g = ctx.createLinearGradient(0, -T / 2, 0, T / 2);
  g.addColorStop(0, st.top);
  g.addColorStop(.28, st.base);
  g.addColorStop(1, st.dark);
  ctx.fillStyle = g;
  const r = Math.min(16, T * .35, L * .1);
  rr(ctx, -L / 2, -T / 2, L, T, r);
  ctx.fill();
  // soft darkness at the bottom
  ctx.save();
  rr(ctx, -L / 2, -T / 2, L, T, r);
  ctx.clip();
  const sh = ctx.createLinearGradient(0, T * .2, 0, T / 2);
  sh.addColorStop(0, 'rgba(0,0,0,0)');
  sh.addColorStop(1, 'rgba(0,0,0,.38)');
  ctx.fillStyle = sh;
  ctx.fillRect(-L / 2, -T / 2, L, T);
  ctx.restore();
}

export function drawPlatforms(ctx, game, cam, time) {
  const z = cam.zoom;
  const viewW = game.renderer.w / z, viewH = game.renderer.h / z;
  const cullL = cam.x - viewW / 2 - 260, cullR = cam.x + viewW / 2 + 260;
  const cullT = cam.y - viewH / 2 - 260, cullB = cam.y + viewH / 2 + 260;

  for (const p of game.level.platforms) {
    if (p.cx < cullL || p.cx > cullR || p.cy < cullT || p.cy > cullB) continue;
    const st = TYPE_STYLE[p.type] || TYPE_STYLE.rock;
    const L = p.len, T = p.t;
    ctx.save();
    ctx.translate(p.cx, p.cy);
    ctx.rotate(p.angle);

    drawBase(ctx, p);

    // texture details
    ctx.save();
    rr(ctx, -L / 2, -T / 2, L, T, Math.min(16, T * .35));
    ctx.clip();

    if (p.type === 'sand') {
      ctx.fillStyle = withA(st.texture, .32);
      for (const s of p.tex.specks) { ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, TAU); ctx.fill(); }
      ctx.strokeStyle = 'rgba(255,235,190,.1)';
      ctx.lineWidth = 1.5;
      for (let i = 0; i < 5; i++) {
        const y = -T / 2 + (i + .5) * (T / 5);
        ctx.beginPath();
        ctx.moveTo(-L / 2, y);
        ctx.bezierCurveTo(-L / 4, y - 4, L / 4, y + 5, L / 2, y - 2);
        ctx.stroke();
      }
    } else if (p.type === 'wood' || p.type === 'deck') {
      ctx.strokeStyle = withA(st.texture, .65);
      ctx.lineWidth = 1.1;
      for (let i = 0; i < 8; i++) {
        const y = -T / 2 + (i + .6) * (T / 8.4);
        ctx.beginPath();
        ctx.moveTo(-L / 2, y);
        ctx.bezierCurveTo(-L / 4, y - 2.5, L / 4, y + 2.5, L / 2, y);
        ctx.stroke();
      }
      ctx.strokeStyle = 'rgba(30,17,7,.55)';
      for (const s of p.tex.seams) {
        ctx.beginPath();
        ctx.moveTo(s, -T / 2);
        ctx.lineTo(s + (p.seed - .5) * 6, T / 2);
        ctx.stroke();
      }
      for (const n of p.tex.nails) {
        ctx.fillStyle = 'rgba(38,30,22,.8)';
        ctx.beginPath(); ctx.arc(n.x, n.y, 1.5, 0, TAU); ctx.fill();
        ctx.fillStyle = 'rgba(210,190,150,.22)';
        ctx.beginPath(); ctx.arc(n.x - .4, n.y - .5, .7, 0, TAU); ctx.fill();
      }
      // iron straps
      if (p.type === 'deck') {
        for (const sx of [-L * .36, L * .36]) {
          ctx.fillStyle = 'rgba(38,36,32,.72)';
          ctx.fillRect(sx - 3, -T / 2, 6, T);
          ctx.fillStyle = 'rgba(160,155,140,.16)';
          ctx.fillRect(sx - 3, -T / 2, 1.4, T);
        }
      }
    } else if (p.type === 'rock') {
      ctx.strokeStyle = withA(st.texture, .7);
      ctx.lineWidth = 1.2;
      for (const c of p.tex.cracks) {
        ctx.beginPath();
        ctx.moveTo(c[0].x, c[0].y);
        for (let i = 1; i < c.length; i++) ctx.lineTo(c[i].x, c[i].y);
        ctx.stroke();
      }
      ctx.fillStyle = 'rgba(190,190,165,.07)';
      for (let i = 0; i < 7; i++) {
        const x = -L / 2 + (i + .35) * (L / 7);
        ctx.beginPath();
        ctx.moveTo(x, -T / 2);
        ctx.lineTo(x + 7, -T / 2 + 10 + (i % 3) * 6);
        ctx.lineTo(x - 3, T / 2);
        ctx.lineTo(x - 8, T / 2);
        ctx.closePath();
        ctx.fill();
      }
    } else if (p.type === 'moss') {
      // rock strata beneath moss cap
      ctx.strokeStyle = 'rgba(20,30,18,.35)';
      ctx.lineWidth = 1.1;
      for (const c of p.tex.cracks) {
        ctx.beginPath();
        ctx.moveTo(c[0].x, c[0].y);
        for (let i = 1; i < c.length; i++) ctx.lineTo(c[i].x, c[i].y);
        ctx.stroke();
      }
      ctx.fillStyle = 'rgba(96,120,66,.9)';
      ctx.fillRect(-L / 2, -T / 2, L, Math.min(18, T * .3));
      // grass tufts along the top
      ctx.strokeStyle = 'rgba(138,166,96,.95)';
      ctx.lineWidth = 1.5;
      for (const t of p.tex.tufts) {
        ctx.beginPath();
        ctx.moveTo(t.x, -T / 2 + 2);
        ctx.quadraticCurveTo(t.x + t.lean * .4, -T / 2 - t.h * .6, t.x + t.lean, -T / 2 - t.h);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(t.x, -T / 2 + 2);
        ctx.quadraticCurveTo(t.x - t.lean * .6, -T / 2 - t.h * .5, t.x - t.lean * 1.2, -T / 2 - t.h * .7);
        ctx.stroke();
      }
    } else if (p.type === 'stone' || p.type === 'gold') {
      ctx.strokeStyle = 'rgba(32,30,25,.5)';
      ctx.lineWidth = 1.3;
      const rows = Math.max(2, Math.floor(T / 24));
      for (let r = 1; r < rows; r++) {
        const y = -T / 2 + (r / rows) * T;
        ctx.beginPath();
        ctx.moveTo(-L / 2, y);
        ctx.lineTo(L / 2, y);
        ctx.stroke();
      }
      for (let r = 0; r < rows; r++) {
        const y0 = -T / 2 + (r / rows) * T;
        const y1 = -T / 2 + ((r + 1) / rows) * T;
        const off = (r % 2) * 28;
        for (let x = -L / 2 + off; x < L / 2; x += 56) {
          ctx.beginPath();
          ctx.moveTo(x, y0);
          ctx.lineTo(x, y1);
          ctx.stroke();
        }
      }
      if (p.type === 'gold') {
        ctx.strokeStyle = 'rgba(255,214,120,.4)';
        ctx.lineWidth = 2;
        for (const v of p.tex.veins) {
          ctx.beginPath();
          ctx.moveTo(v.x0, v.y);
          ctx.bezierCurveTo(v.x0 + 10, v.y - 6, v.x1 - 10, v.y + 6, v.x1, v.y);
          ctx.stroke();
        }
      }
    }

    ctx.restore();

    // bright walkable rim
    ctx.strokeStyle = st.edge;
    ctx.lineWidth = p.type === 'gold' ? 3.5 : 2.4;
    ctx.globalAlpha = p.type === 'gold' ? .95 : .72;
    ctx.beginPath();
    ctx.moveTo(-L / 2 + 2, -T / 2 + 1);
    ctx.lineTo(L / 2 - 2, -T / 2 + 1);
    ctx.stroke();
    ctx.globalAlpha = 1;

    // end grain / edge shade
    ctx.strokeStyle = 'rgba(0,0,0,.28)';
    ctx.lineWidth = 1;
    rr(ctx, -L / 2, -T / 2, L, T, Math.min(16, T * .35));
    ctx.stroke();

    // rope wraps for ship timber
    if (p.ship && p.type === 'wood') {
      ctx.strokeStyle = 'rgba(168,140,92,.5)';
      ctx.lineWidth = 1.2;
      for (let i = 0; i < 3; i++) {
        const x = -L / 2 + 14 + i * 5;
        ctx.beginPath();
        ctx.moveTo(x, -T / 2);
        ctx.lineTo(x + 3, T / 2);
        ctx.stroke();
      }
    }

    ctx.restore();
  }
}

/* ══════════════════════════════════════════════════════════════
   PROPS — palms, wrecks, ruins, torches and the hoard
   ══════════════════════════════════════════════════════════════ */

import {
  TAU, clamp, lerp, hashStr, mulberry32, rr, ellipse, poly, blob, shadowBlob,
} from './paint.js';

function glow(ctx, x, y, r, color, alpha = .5) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, color.replace('A', String(alpha)));
  g.addColorStop(.4, color.replace('A', String(alpha * .45)));
  g.addColorStop(1, color.replace('A', '0'));
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TAU);
  ctx.fill();
}

export function drawProp(ctx, prop, time, game) {
  ctx.save();
  const s = prop.s || 1;
  ctx.translate(prop.x, prop.y);
  if (prop.tilt) ctx.rotate(prop.tilt);
  ctx.scale(prop.flip ? -s : s, s);
  const rand = mulberry32(hashStr(prop.type + prop.x + prop.y));
  switch (prop.type) {
    case 'palm': palm(ctx, time, rand, prop); break;
    case 'fern': fern(ctx, time, rand); break;
    case 'sign': sign(ctx, time); break;
    case 'skeleton': skeleton(ctx, rand); break;
    case 'barrel': barrel(ctx, rand); break;
    case 'crate': crate(ctx, rand); break;
    case 'driftwood': driftwood(ctx, rand); break;
    case 'seagull': seagull(ctx, time, rand); break;
    case 'hull': hull(ctx, time, rand); break;
    case 'mast': brokenMast(ctx, time, rand); break;
    case 'sail': sail(ctx, time); break;
    case 'lantern': lantern(ctx, time); break;
    case 'ropehang': ropeHang(ctx, time, rand); break;
    case 'waterfall': waterfall(ctx, time, rand); break;
    case 'vine': vine(ctx, time, rand); break;
    case 'skull': skull(ctx, rand); break;
    case 'torch': torch(ctx, time); break;
    case 'column': column(ctx, rand, prop.broken); break;
    case 'arch': arch(ctx, rand); break;
    case 'statue': statue(ctx, rand); break;
    case 'skullgate': skullGate(ctx, time); break;
    case 'goldpile': goldPile(ctx, time, rand); break;
    case 'bones': bones(ctx, rand); break;
    default: break;
  }
  ctx.restore();
}

/* ── jungle ─────────────────────────────────────────────── */
function palm(ctx, time, rand) {
  const h = 130 + rand() * 70;
  const sway = Math.sin(time * .7 + rand() * 9) * 3;
  shadowBlob(ctx, 4, 3, 42, 10, .28);
  // base rocks
  ctx.fillStyle = '#3c3a2b';
  blob(ctx, 0, 0, 24, 8, rand, 7, .2); ctx.fill();
  // trunk
  ctx.strokeStyle = '#5e4428';
  ctx.lineWidth = 8;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(0, -4);
  ctx.bezierCurveTo(2, -h * .35, 12, -h * .7, 8 + sway, -h);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(176,134,82,.4)';
  ctx.lineWidth = 2.2;
  ctx.beginPath();
  ctx.moveTo(-2, -6);
  ctx.bezierCurveTo(0, -h * .35, 10, -h * .7, 6 + sway, -h);
  ctx.stroke();
  // trunk rings
  ctx.strokeStyle = 'rgba(48,31,16,.55)';
  ctx.lineWidth = 1;
  for (let i = 1; i < 8; i++) {
    const t = i / 8;
    const x = lerp(0, 8 + sway, t) + Math.sin(t * 3) * 5;
    const y = -h * t;
    ctx.beginPath();
    ctx.moveTo(x - 4, y);
    ctx.quadraticCurveTo(x, y + 2, x + 4, y);
    ctx.stroke();
  }
  // fronds
  const topX = 8 + sway, topY = -h;
  const n = 7;
  for (let i = 0; i < n; i++) {
    const a = -Math.PI * .95 + (i / (n - 1)) * Math.PI * 1.9 + Math.sin(time * .8 + i) * .04;
    const len = 46 + (i % 3) * 14;
    const ex = topX + Math.cos(a) * len;
    const ey = topY + Math.sin(a) * len * .55 + 12;
    const mx = topX + Math.cos(a) * len * .55;
    const my = topY + Math.sin(a) * len * .55 - 10;
    const px = -Math.sin(a) * 9, py = Math.cos(a) * 4;
    ctx.fillStyle = i % 3 === 0 ? '#496b37' : i % 3 === 1 ? '#3d5c2e' : '#557a3e';
    ctx.beginPath();
    ctx.moveTo(topX, topY);
    ctx.quadraticCurveTo(mx + px, my + py, ex, ey);
    ctx.quadraticCurveTo(mx - px, my - py, topX, topY);
    ctx.fill();
    ctx.strokeStyle = 'rgba(24,38,18,.5)';
    ctx.lineWidth = .8;
    ctx.beginPath();
    ctx.moveTo(topX, topY);
    ctx.quadraticCurveTo(mx, my, ex, ey);
    ctx.stroke();
    // leaf notches
    for (let j = 1; j < 5; j++) {
      const t = j / 5;
      const lx = lerp(topX, ex, t) + Math.cos(a + 1.57) * 4;
      const ly = lerp(topY, ey, t) + Math.sin(a + 1.57) * 4;
      ctx.beginPath();
      ctx.moveTo(lx, ly - 2);
      ctx.lineTo(lx + Math.cos(a + 1.2) * 9, ly + Math.sin(a + 1.2) * 9 + 2);
      ctx.stroke();
    }
  }
  // coconuts
  ctx.fillStyle = '#4a3520';
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.arc(topX + (rand() - .5) * 10, topY + 4 + (rand() - .5) * 6, 3.2, 0, TAU);
    ctx.fill();
  }
}

function fern(ctx, time, rand) {
  const n = 5 + Math.floor(rand() * 3);
  for (let i = 0; i < n; i++) {
    const a = -Math.PI * .9 + (i / (n - 1)) * Math.PI * 1.8;
    const len = 26 + rand() * 26;
    const sway = Math.sin(time * 1.1 + i) * 2;
    const ex = Math.cos(a) * len + sway, ey = Math.sin(a) * len * .5 - len * .4;
    ctx.strokeStyle = '#4b6b39';
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.quadraticCurveTo(Math.cos(a) * len * .5, -len * .55, ex, ey);
    ctx.stroke();
    for (let j = 1; j < 6; j++) {
      const t = j / 6;
      const x = lerp(0, ex, t), y = lerp(0, ey, t);
      ctx.strokeStyle = j % 2 ? '#5f8345' : '#426132';
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + Math.cos(a + 1.2) * 7, y + Math.sin(a + 1.2) * 7 - 2);
      ctx.stroke();
    }
  }
}

function vine(ctx, time, rand) {
  const len = 120 + rand() * 180;
  const x0 = 0;
  ctx.strokeStyle = 'rgba(53,76,42,.85)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x0, 0);
  ctx.bezierCurveTo(12, len * .3, -10, len * .65, 4, len);
  ctx.stroke();
  const n = Math.floor(len / 18);
  for (let i = 0; i < n; i++) {
    const t = (i + .5) / n;
    const x = x0 + Math.sin(t * 5 + rand()) * 7;
    const y = len * t;
    const side = i % 2 ? 1 : -1;
    const sway = Math.sin(time * .9 + i) * 1.4;
    ctx.fillStyle = i % 3 === 0 ? '#557a40' : '#436331';
    ctx.beginPath();
    ctx.ellipse(x + side * 5 + sway, y, 4.5, 2.2, side * .5, 0, TAU);
    ctx.fill();
  }
}

function waterfall(ctx, time, rand) {
  const h = 260;
  const w = 34;
  ctx.save();
  // rock lip
  ctx.fillStyle = '#414438';
  blob(ctx, 0, 0, 34, 12, rand, 7, .2); ctx.fill();
  // fall
  for (let i = 0; i < 8; i++) {
    const x = -w / 2 + (i / 7) * w;
    const phase = (time * .8 + i * .13) % 1;
    const g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, 'rgba(198,227,214,.06)');
    g.addColorStop(.4, `rgba(190,224,212,${.18 + .1 * Math.sin(time * 2 + i)})`);
    g.addColorStop(1, 'rgba(160,205,196,.02)');
    ctx.strokeStyle = g;
    ctx.lineWidth = 2 + (i % 3);
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.bezierCurveTo(x + 4, h * .3, x - 5 + Math.sin(time + i) * 2, h * .7, x + 2, h);
    ctx.stroke();
    ctx.fillStyle = 'rgba(220,240,232,.22)';
    ctx.beginPath();
    ctx.arc(x + Math.sin(i * 4) * 4, h * phase, 1.6, 0, TAU);
    ctx.fill();
  }
  // mist
  glow(ctx, 0, h - 10, 40, 'rgba(180,220,210,A)', .12);
  ctx.restore();
}

/* ── beach ──────────────────────────────────────────────── */
function sign(ctx, time) {
  shadowBlob(ctx, 0, 2, 24, 5, .25);
  ctx.fillStyle = '#4b3520';
  ctx.fillRect(-2.5, -46, 5, 48);
  ctx.save();
  ctx.translate(0, -40);
  ctx.rotate(Math.sin(time * .4) * .012 - .03);
  ctx.fillStyle = '#6b4a29';
  rr(ctx, -34, -16, 68, 30, 2); ctx.fill();
  ctx.strokeStyle = '#3d2a16'; ctx.lineWidth = 1.5; ctx.stroke();
  ctx.fillStyle = '#d4b378';
  ctx.font = "12px 'Pirata One', serif";
  ctx.textAlign = 'center';
  ctx.fillText('THE HOARD', 0, -3);
  ctx.font = "9px 'IM Fell English', serif";
  ctx.fillText('↑ that way ↑', 0, 9);
  ctx.fillStyle = 'rgba(30,20,10,.6)';
  ctx.beginPath(); ctx.arc(-28, -12, 1.4, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.arc(28, -12, 1.4, 0, TAU); ctx.fill();
  ctx.restore();
}

function skeleton(ctx, rand) {
  shadowBlob(ctx, 0, 1, 30, 6, .25);
  ctx.save();
  ctx.rotate(-.25);
  ctx.strokeStyle = '#d8cba6';
  ctx.lineWidth = 2.6;
  ctx.lineCap = 'round';
  // ribs
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.arc(0, -6 + i * 2, 9 + i * 2, .3, Math.PI - .3);
    ctx.stroke();
  }
  // spine
  ctx.beginPath(); ctx.moveTo(-12, -4); ctx.lineTo(12, -4); ctx.stroke();
  // arm
  ctx.beginPath(); ctx.moveTo(-4, -8); ctx.quadraticCurveTo(-18, -18, -26, -12); ctx.stroke();
  // skull
  ctx.fillStyle = '#e3d6b0';
  ctx.beginPath(); ctx.ellipse(17, -6, 7, 8, 0, 0, TAU); ctx.fill();
  ctx.fillStyle = '#2a2418';
  ctx.beginPath(); ctx.arc(19, -8, 1.8, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.arc(14, -8, 1.8, 0, TAU); ctx.fill();
  // hat
  ctx.fillStyle = '#3c3428';
  ctx.beginPath(); ctx.ellipse(17, -13, 11, 3, -.1, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.ellipse(17, -16, 6, 4, -.1, 0, TAU); ctx.fill();
  // bottle
  ctx.fillStyle = 'rgba(88,120,98,.65)';
  ctx.fillRect(-32, -10, 4, 10);
  ctx.fillRect(-31, -14, 2, 5);
  ctx.restore();
}

function barrel(ctx, rand) {
  shadowBlob(ctx, 0, 1, 18, 4, .28);
  const g = ctx.createLinearGradient(-16, 0, 16, 0);
  g.addColorStop(0, '#4a301a');
  g.addColorStop(.45, '#8d602f');
  g.addColorStop(1, '#3f2916');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(-15, 0);
  ctx.bezierCurveTo(-19, -14, -15, -28, -13, -32);
  ctx.lineTo(13, -32);
  ctx.bezierCurveTo(15, -28, 19, -14, 15, 0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#2b1b0d'; ctx.lineWidth = 1.4; ctx.stroke();
  ctx.strokeStyle = 'rgba(35,35,32,.85)';
  ctx.lineWidth = 2.6;
  for (const y of [-7, -25]) {
    ctx.beginPath();
    ctx.moveTo(-17, y); ctx.quadraticCurveTo(0, y + 1, 17, y);
    ctx.stroke();
  }
  ctx.strokeStyle = 'rgba(166,130,80,.25)';
  ctx.lineWidth = 1;
  for (let i = -2; i <= 2; i++) {
    ctx.beginPath();
    ctx.moveTo(i * 5, -1);
    ctx.lineTo(i * 4, -31);
    ctx.stroke();
  }
  ctx.fillStyle = '#3a2715';
  ctx.beginPath(); ctx.ellipse(0, -32, 13, 3.4, 0, 0, TAU); ctx.fill();
}

function crate(ctx, rand) {
  shadowBlob(ctx, 0, 1, 19, 4, .28);
  const g = ctx.createLinearGradient(-17, -34, 17, 0);
  g.addColorStop(0, '#8b6136');
  g.addColorStop(1, '#5a3c20');
  ctx.fillStyle = g;
  ctx.fillRect(-17, -32, 34, 32);
  ctx.strokeStyle = '#392512'; ctx.lineWidth = 1.6; ctx.strokeRect(-17, -32, 34, 32);
  ctx.strokeStyle = 'rgba(60,40,20,.8)'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(-17, -32); ctx.lineTo(17, 0); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(17, -32); ctx.lineTo(-17, 0); ctx.stroke();
  ctx.strokeStyle = 'rgba(196,158,104,.25)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(-15, -30); ctx.lineTo(-15, -2); ctx.stroke();
}

function driftwood(ctx, rand) {
  ctx.save();
  ctx.rotate(-.08);
  ctx.fillStyle = '#6a5338';
  ctx.beginPath();
  ctx.moveTo(-50, 0);
  ctx.bezierCurveTo(-30, -10, 30, -12, 55, -2);
  ctx.lineTo(52, 6);
  ctx.bezierCurveTo(20, -3, -20, 4, -52, 8);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(40,28,16,.5)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.moveTo(-40 + i * 20, -1 - i);
    ctx.lineTo(-20 + i * 20, 3 - i);
    ctx.stroke();
  }
  ctx.restore();
}

function seagull(ctx, time, rand) {
  const flap = Math.sin(time * 4 + rand() * 9);
  ctx.strokeStyle = 'rgba(238,232,210,.85)';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(-7, 0);
  ctx.quadraticCurveTo(-3, -4 - flap * 4, 0, 0);
  ctx.quadraticCurveTo(3, -4 - flap * 4, 7, 0);
  ctx.stroke();
  ctx.fillStyle = 'rgba(238,232,210,.85)';
  ctx.beginPath(); ctx.ellipse(0, .5, 2, 1, 0, 0, TAU); ctx.fill();
}

/* ── wreck ──────────────────────────────────────────────── */
function hull(ctx, time, rand) {
  ctx.save();
  ctx.rotate(-.16);
  const g = ctx.createLinearGradient(0, -140, 0, 220);
  g.addColorStop(0, '#3c2a1b');
  g.addColorStop(.55, '#2c1f14');
  g.addColorStop(1, '#1c1510');
  // hull body
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(-250, -80);
  ctx.bezierCurveTo(-120, -130, 110, -110, 240, -40);
  ctx.bezierCurveTo(280, 60, 240, 180, 160, 230);
  ctx.lineTo(-180, 210);
  ctx.bezierCurveTo(-270, 130, -290, 20, -250, -80);
  ctx.closePath();
  ctx.fill();
  // planks
  ctx.strokeStyle = 'rgba(120,88,52,.2)';
  ctx.lineWidth = 2;
  for (let i = 0; i < 9; i++) {
    const y = -70 + i * 32;
    ctx.beginPath();
    ctx.moveTo(-265, y);
    ctx.bezierCurveTo(-80, y + 14, 120, y + 8, 260, y - 10);
    ctx.stroke();
  }
  // ribs
  ctx.strokeStyle = 'rgba(14,10,7,.7)';
  ctx.lineWidth = 7;
  for (let i = -6; i <= 6; i++) {
    const x = i * 36;
    ctx.beginPath();
    ctx.moveTo(x, -100);
    ctx.quadraticCurveTo(x + i * 3, 40, x + i * 10, 222);
    ctx.stroke();
  }
  // broken side opening
  ctx.fillStyle = 'rgba(6,9,9,.82)';
  ctx.beginPath();
  ctx.moveTo(30, -90);
  ctx.bezierCurveTo(105, -75, 150, -20, 140, 60);
  ctx.bezierCurveTo(100, 90, 40, 80, 10, 30);
  ctx.closePath();
  ctx.fill();
  // rib tips
  ctx.strokeStyle = '#5a4128';
  ctx.lineWidth = 5;
  for (let i = 0; i < 7; i++) {
    const x = -220 + i * 70;
    ctx.beginPath();
    ctx.moveTo(x, -95);
    ctx.quadraticCurveTo(x + 12, -150 - (i % 3) * 18, x + 26, -168 - (i % 3) * 22);
    ctx.stroke();
  }
  // seaweed
  ctx.strokeStyle = 'rgba(57,83,48,.7)';
  ctx.lineWidth = 2;
  for (let i = 0; i < 12; i++) {
    const x = -230 + rand() * 470;
    const y = 190 + rand() * 40;
    const sw = Math.sin(time * .8 + i) * 5;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.bezierCurveTo(x + sw, y + 30, x - sw, y + 60, x + 4, y + 90);
    ctx.stroke();
  }
  ctx.restore();
  // tattered sail remnants
  ctx.save();
  ctx.globalAlpha = .5;
  ctx.fillStyle = '#9d8a69';
  ctx.beginPath();
  ctx.moveTo(-40, -120);
  ctx.quadraticCurveTo(-10, -60, -60, 10);
  ctx.quadraticCurveTo(-100, -40, -130, -100);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#14201c';
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.ellipse(-60 + i * 12, -80 + i * 18, 8, 4, .4, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function brokenMast(ctx, time, rand) {
  ctx.save();
  ctx.rotate(.22);
  ctx.fillStyle = '#3c2a19';
  ctx.beginPath();
  ctx.moveTo(-11, 0);
  ctx.lineTo(-7, -300);
  ctx.lineTo(3, -306);
  ctx.lineTo(9, 0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(155,118,74,.25)'; ctx.lineWidth = 1.6;
  for (let i = 1; i < 7; i++) {
    ctx.beginPath();
    ctx.moveTo(-9, -i * 40);
    ctx.lineTo(-2, -i * 40 + 1);
    ctx.stroke();
  }
  // yardarm
  ctx.strokeStyle = '#332415'; ctx.lineWidth = 8;
  ctx.beginPath(); ctx.moveTo(-92, -238); ctx.lineTo(100, -256); ctx.stroke();
  // rigging
  ctx.strokeStyle = 'rgba(190,168,124,.35)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(-90, -240); ctx.lineTo(-30, -10); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(98, -258); ctx.lineTo(30, -10); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-88, -240); ctx.lineTo(-48, -150); ctx.stroke();
  ctx.restore();
}

function sail(ctx, time, rand) {
  ctx.save();
  const w = 150, h = 120;
  const g = ctx.createLinearGradient(0, 0, 0, h);
  g.addColorStop(0, 'rgba(185,166,128,.62)');
  g.addColorStop(1, 'rgba(120,105,80,.35)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(-w / 2, 0);
  ctx.bezierCurveTo(-w / 2 + 20, h * .4, -w / 2 + 10, h * .8, -w / 2 + 34 + Math.sin(time) * 4, h);
  ctx.lineTo(w / 2 - 20, h - 16);
  ctx.bezierCurveTo(w / 2 - 10, h * .6, w / 2 + 8, h * .2, w / 2, 0);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(22,30,25,.9)';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.ellipse((rand() - .5) * w * .7, h * (.25 + rand() * .6), 5 + rand() * 8, 2 + rand() * 4, rand(), 0, TAU);
    ctx.fill();
  }
  ctx.strokeStyle = 'rgba(70,56,38,.5)'; ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.moveTo(-w / 2, 2); ctx.lineTo(w / 2, 2); ctx.stroke();
  ctx.restore();
}

function lantern(ctx, time) {
  ctx.strokeStyle = '#3a2a18'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(0, -26); ctx.stroke();
  ctx.fillStyle = '#2d2113';
  ctx.fillRect(-5, -7, 10, 8);
  ctx.fillStyle = 'rgba(255,181,91,.9)';
  ctx.fillRect(-4, -19, 8, 11);
  ctx.strokeStyle = '#241a0f'; ctx.lineWidth = 1.4;
  ctx.strokeRect(-5.5, -20, 11, 13);
  ctx.strokeStyle = '#3a2a18';
  ctx.beginPath(); ctx.moveTo(-6, -20); ctx.lineTo(0, -26); ctx.lineTo(6, -20); ctx.stroke();
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  glow(ctx, 0, -14, 34, 'rgba(255,170,80,A)', .24 + Math.sin(time * 5) * .04);
  ctx.restore();
}

function ropeHang(ctx, time, rand) {
  const len = 170;
  ctx.strokeStyle = 'rgba(160,136,94,.65)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.bezierCurveTo(10, len * .3, -8, len * .7, 2, len);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(70,55,34,.8)'; ctx.lineWidth = 1;
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(0 + Math.sin(i) * 2, 20 + i * 32, 3, 0, TAU);
    ctx.stroke();
  }
  // anchor
  ctx.save();
  ctx.translate(2, len + 8);
  ctx.strokeStyle = '#47504e'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(0, -10); ctx.lineTo(0, 14); ctx.stroke();
  ctx.beginPath(); ctx.arc(0, 14, 10, .2, Math.PI - .2); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-6, -4); ctx.lineTo(0, -11); ctx.lineTo(6, -4); ctx.stroke();
  ctx.restore();
}

/* ── ruins ──────────────────────────────────────────────── */
function torch(ctx, time) {
  ctx.fillStyle = '#3b2a17';
  ctx.fillRect(-2.5, -46, 5, 48);
  ctx.fillStyle = '#5b4326';
  ctx.fillRect(-4, -48, 8, 6);
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const flick = Math.sin(time * 9) * .12 + Math.sin(time * 13.7) * .08;
  glow(ctx, 0, -56, 46, 'rgba(255,166,70,A)', .26 + flick);
  glow(ctx, 0, -54, 14, 'rgba(255,235,170,A)', .5 + flick);
  ctx.restore();
  // flame
  const f = Math.sin(time * 7) * 2;
  ctx.fillStyle = 'rgba(255,186,84,.9)';
  ctx.beginPath();
  ctx.moveTo(0, -48);
  ctx.bezierCurveTo(8, -58, 7, -70 + f, 2, -78 - f);
  ctx.bezierCurveTo(-2, -70 - f, -8, -60, 0, -48);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,240,192,.9)';
  ctx.beginPath();
  ctx.moveTo(0, -50);
  ctx.bezierCurveTo(3, -58, 2, -64, 0, -68 + f * .5);
  ctx.bezierCurveTo(-2, -62, -3, -56, 0, -50);
  ctx.fill();
}

function column(ctx, rand, broken = .5) {
  const h = 90 + rand() * 60;
  shadowBlob(ctx, 2, 2, 26, 5, .25);
  // base
  ctx.fillStyle = '#5c5a4e';
  ctx.fillRect(-18, -8, 36, 8);
  ctx.fillStyle = '#7f7c6b';
  ctx.fillRect(-14, -12, 28, 5);
  // shaft
  const g = ctx.createLinearGradient(-12, 0, 12, 0);
  g.addColorStop(0, '#46443a');
  g.addColorStop(.4, '#8b8978');
  g.addColorStop(1, '#4e4c41');
  ctx.fillStyle = g;
  ctx.fillRect(-11, -h, 22, h - 12);
  // flutes
  ctx.strokeStyle = 'rgba(40,38,32,.4)'; ctx.lineWidth = 1;
  for (let i = -2; i <= 2; i++) {
    ctx.beginPath(); ctx.moveTo(i * 4, -h); ctx.lineTo(i * 4, -10); ctx.stroke();
  }
  // broken top
  if (broken > .3) {
    ctx.fillStyle = '#292720';
    ctx.beginPath();
    ctx.moveTo(-11, -h);
    ctx.lineTo(-4, -h + 8 + broken * 10);
    ctx.lineTo(2, -h + 2);
    ctx.lineTo(8, -h + 12);
    ctx.lineTo(11, -h);
    ctx.closePath();
    ctx.fill();
  } else {
    ctx.fillStyle = '#8d8a78';
    ctx.fillRect(-14, -h - 6, 28, 7);
  }
  // moss
  ctx.fillStyle = 'rgba(91,116,68,.35)';
  ctx.fillRect(-11, -h + 20, 22, 12);
}

function arch(ctx, rand) {
  ctx.save();
  // pillars
  for (const side of [-1, 1]) {
    const x = side * 94;
    const g = ctx.createLinearGradient(x - 20, 0, x + 20, 0);
    g.addColorStop(0, '#3d3b32');
    g.addColorStop(.45, '#777566');
    g.addColorStop(1, '#413f36');
    ctx.fillStyle = g;
    ctx.fillRect(x - 20, -150, 40, 150);
    ctx.strokeStyle = 'rgba(30,29,24,.5)';
    ctx.lineWidth = 1.2;
    for (let i = 1; i < 5; i++) {
      ctx.beginPath(); ctx.moveTo(x - 20, -150 + i * 30); ctx.lineTo(x + 20, -150 + i * 30); ctx.stroke();
    }
    ctx.fillStyle = '#4f4d42';
    ctx.fillRect(x - 25, -12, 50, 12);
  }
  // arch
  ctx.strokeStyle = '#6e6c5d';
  ctx.lineWidth = 34;
  ctx.beginPath();
  ctx.arc(0, -150, 94, Math.PI + .18, -.18);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(34,32,27,.5)';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.arc(0, -150, 111, Math.PI + .18, -.18);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(0, -150, 77, Math.PI + .18, -.18);
  ctx.stroke();
  // keystone
  ctx.fillStyle = '#918e7c';
  ctx.beginPath();
  ctx.moveTo(-10, -258); ctx.lineTo(10, -258); ctx.lineTo(7, -240); ctx.lineTo(-7, -240);
  ctx.closePath(); ctx.fill();
  // hanging vines
  ctx.strokeStyle = 'rgba(70,92,55,.7)'; ctx.lineWidth = 1.5;
  for (let i = 0; i < 5; i++) {
    const x = -70 + i * 35;
    const len = 20 + rand() * 50;
    ctx.beginPath(); ctx.moveTo(x, -238); ctx.quadraticCurveTo(x + 6, -238 + len * .5, x + 2, -238 + len); ctx.stroke();
  }
  ctx.restore();
}

function statue(ctx, rand) {
  shadowBlob(ctx, 0, 2, 30, 6, .28);
  ctx.fillStyle = '#5c5a4e';
  ctx.fillRect(-26, -14, 52, 14);
  const g = ctx.createLinearGradient(-20, 0, 20, 0);
  g.addColorStop(0, '#45443a'); g.addColorStop(.45, '#898674'); g.addColorStop(1, '#4a483d');
  ctx.fillStyle = g;
  // coat body
  ctx.beginPath();
  ctx.moveTo(-16, -14);
  ctx.lineTo(-18, -74);
  ctx.quadraticCurveTo(0, -86, 18, -74);
  ctx.lineTo(16, -14);
  ctx.closePath();
  ctx.fill();
  // head
  ctx.beginPath(); ctx.arc(0, -92, 12, 0, TAU); ctx.fill();
  // tricorn
  ctx.beginPath();
  ctx.moveTo(-22, -98); ctx.quadraticCurveTo(0, -116, 22, -98);
  ctx.quadraticCurveTo(0, -104, -22, -98);
  ctx.fill();
  // arm + cutlass
  ctx.strokeStyle = '#6f6c5c'; ctx.lineWidth = 6; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(12, -65); ctx.quadraticCurveTo(30, -55, 36, -36); ctx.stroke();
  ctx.strokeStyle = '#85826f'; ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.moveTo(36, -36); ctx.lineTo(48, -8); ctx.stroke();
  // weathering
  ctx.strokeStyle = 'rgba(40,40,32,.4)'; ctx.lineWidth = 1;
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.moveTo(-12 + i * 8, -70 + rand() * 20);
    ctx.lineTo(-16 + i * 9, -30 + rand() * 10);
    ctx.stroke();
  }
  // moss
  ctx.fillStyle = 'rgba(91,116,68,.4)';
  ctx.fillRect(-18, -74, 10, 20);
}

function skullGate(ctx, time) {
  ctx.save();
  // giant skull carved into the rock
  const g = ctx.createRadialGradient(0, -150, 30, 0, -150, 280);
  g.addColorStop(0, '#4a4639');
  g.addColorStop(.65, '#34322a');
  g.addColorStop(1, 'rgba(30,29,24,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(0, -160, 260, 210, 0, 0, TAU);
  ctx.fill();
  // bone color
  ctx.fillStyle = '#5b5748';
  ctx.beginPath();
  ctx.ellipse(0, -175, 150, 135, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#6c6754';
  ctx.beginPath();
  ctx.ellipse(0, -210, 115, 92, 0, 0, TAU);
  ctx.fill();
  // eye sockets
  for (const side of [-1, 1]) {
    const ex = side * 52, ey = -214;
    const eg = ctx.createRadialGradient(ex, ey, 2, ex, ey, 46);
    eg.addColorStop(0, 'rgba(255,206,96,.45)');
    eg.addColorStop(.55, 'rgba(18,16,12,.95)');
    eg.addColorStop(1, '#151410');
    ctx.fillStyle = eg;
    ctx.beginPath();
    ctx.ellipse(ex, ey, 40, 35, side * .12, 0, TAU);
    ctx.fill();
    // inner glow
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    glow(ctx, ex, ey, 40, 'rgba(255,180,60,A)', .24 + Math.sin(time * 2 + side) * .06);
    ctx.restore();
  }
  // nose
  ctx.fillStyle = '#24221b';
  ctx.beginPath();
  ctx.moveTo(0, -160); ctx.lineTo(18, -126); ctx.lineTo(-18, -126); ctx.closePath();
  ctx.fill();
  // teeth
  ctx.fillStyle = '#7a7460';
  for (let i = -4; i <= 4; i++) {
    const x = i * 22;
    ctx.fillRect(x - 8, -100, 16, 26 - Math.abs(i) * 2);
  }
  ctx.fillStyle = '#1b1913';
  ctx.fillRect(-98, -88, 196, 14);
  // vines
  ctx.strokeStyle = 'rgba(80,105,62,.6)'; ctx.lineWidth = 2;
  for (let i = 0; i < 6; i++) {
    const x = -160 + i * 64;
    const len = 50 + (i % 3) * 40;
    ctx.beginPath();
    ctx.moveTo(x, -300);
    ctx.bezierCurveTo(x + 14, -300 + len * .4, x - 10, -300 + len * .8, x + 4, -300 + len);
    ctx.stroke();
  }
  ctx.restore();
}

function goldPile(ctx, time, rand) {
  shadowBlob(ctx, 0, 1, 26, 5, .2);
  ctx.fillStyle = '#6b4d1b';
  blob(ctx, 0, -6, 28, 12, rand, 8, .2); ctx.fill();
  const g = ctx.createRadialGradient(-6, -16, 2, 0, -8, 30);
  g.addColorStop(0, '#ffe9a8');
  g.addColorStop(.4, '#e8bb56');
  g.addColorStop(1, '#8b6321');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(0, -8, 24, 13, 0, Math.PI, 0);
  ctx.fill();
  // coins
  for (let i = 0; i < 16; i++) {
    const a = rand() * Math.PI, r = rand() * 23;
    const x = Math.cos(Math.PI + a) * r, y = -4 - Math.sin(a) * r * .5;
    ctx.fillStyle = i % 3 ? '#d9a844' : '#f3d17a';
    ctx.beginPath(); ctx.ellipse(x, y, 2.5, 1.3, rand(), 0, TAU); ctx.fill();
  }
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  glow(ctx, 0, -12, 34, 'rgba(255,206,96,A)', .1 + Math.sin(time * 3) * .03);
  ctx.restore();
}

function bones(ctx, rand) {
  ctx.strokeStyle = '#cfc19c'; ctx.lineWidth = 2.4; ctx.lineCap = 'round';
  for (let i = 0; i < 4; i++) {
    const x = -12 + i * 8, y = -2 - (i % 2) * 3;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + 10, y - 3);
    ctx.stroke();
    ctx.beginPath(); ctx.arc(x - 1, y, 1.6, 0, TAU); ctx.stroke();
  }
  ctx.fillStyle = '#d8cba6';
  ctx.beginPath(); ctx.ellipse(14, -6, 5.5, 5, 0, 0, TAU); ctx.fill();
  ctx.fillStyle = '#2a2418';
  ctx.beginPath(); ctx.arc(15, -7, 1.2, 0, TAU); ctx.fill();
}

function skull(ctx, rand) {
  ctx.save();
  ctx.fillStyle = '#cfc3a0';
  ctx.beginPath();
  ctx.ellipse(0, -10, 13, 12, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#201d15';
  ctx.beginPath(); ctx.ellipse(-5, -12, 3.2, 3.8, .2, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.ellipse(5, -12, 3.2, 3.8, -.2, 0, TAU); ctx.fill();
  ctx.fillStyle = '#a89c7c';
  ctx.beginPath();
  ctx.moveTo(-7, -3); ctx.lineTo(7, -3); ctx.lineTo(4, 3); ctx.lineTo(-4, 3);
  ctx.closePath(); ctx.fill();
  ctx.strokeStyle = '#d8cba6'; ctx.lineWidth = 1.6;
  ctx.beginPath(); ctx.moveTo(-9, 2); ctx.lineTo(-19, 8); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(9, 2); ctx.lineTo(19, 8); ctx.stroke();
  ctx.restore();
}

/* ── treasure ───────────────────────────────────────────── */
export function drawChest(ctx, x, y, time, open, scale = 1) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(scale, scale);
  shadowBlob(ctx, 0, 3, 52, 10, .35);
  // glow
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  glow(ctx, 0, -30, 110, 'rgba(255,190,70,A)', .12 + open * .28);
  ctx.restore();
  const bodyG = ctx.createLinearGradient(0, -34, 0, 4);
  bodyG.addColorStop(0, '#8a5a26');
  bodyG.addColorStop(1, '#4c2d10');
  ctx.fillStyle = bodyG;
  rr(ctx, -44, -34, 88, 38, 3); ctx.fill();
  ctx.strokeStyle = '#2a1707'; ctx.lineWidth = 2.4; ctx.stroke();
  // bands
  ctx.fillStyle = '#c79b45';
  for (const bx of [-26, 26]) ctx.fillRect(bx - 3, -34, 6, 38);
  ctx.fillStyle = '#e3ba62';
  // lid
  ctx.save();
  ctx.translate(0, -34);
  ctx.rotate(-open * 1.12);
  const lidG = ctx.createLinearGradient(0, -26, 0, 0);
  lidG.addColorStop(0, '#a06c2e');
  lidG.addColorStop(1, '#6d4519');
  ctx.fillStyle = lidG;
  ctx.beginPath();
  ctx.moveTo(-44, 0);
  ctx.quadraticCurveTo(-44, -28, -22, -30);
  ctx.lineTo(22, -30);
  ctx.quadraticCurveTo(44, -28, 44, 0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#2a1707'; ctx.lineWidth = 2.4; ctx.stroke();
  ctx.fillStyle = '#c79b45';
  for (const bx of [-26, 26]) ctx.fillRect(bx - 3, -28, 6, 28);
  ctx.restore();
  // gold interior
  if (open > .05) {
    ctx.fillStyle = 'rgba(255,224,140,.9)';
    ctx.fillRect(-40, -36, 80, 6 + open * 6);
    ctx.fillStyle = '#ffe9a8';
    ctx.beginPath(); ctx.ellipse(0, -34, 36, 6, 0, 0, TAU); ctx.fill();
  }
  // lock
  ctx.fillStyle = '#e6c168';
  rr(ctx, -8, -30, 16, 16, 2); ctx.fill();
  ctx.fillStyle = '#3a2509';
  ctx.beginPath(); ctx.arc(0, -23, 2.6, 0, TAU); ctx.fill();
  ctx.fillRect(-1, -23, 2, 6);
  // gold spilling
  for (let i = 0; i < 12; i++) {
    const a = -Math.PI * .9 + (i / 11) * Math.PI * .8;
    ctx.fillStyle = i % 2 ? '#f3d17a' : '#d9a844';
    ctx.beginPath();
    ctx.ellipse(Math.cos(a) * 48, -4 + Math.sin(a) * 6, 3.2, 1.8, a, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

/* ══════════════════════════════════════════════════════════════
   CHARACTER — the barrel, the beard, the pole and the hook
   ══════════════════════════════════════════════════════════════ */

import { TAU, clamp, lerp, rr, ellipse } from './paint.js';

export function drawPole(ctx, game, time) {
  const p = game.pole;
  if (!p) return;
  const L = 318, T = 17;
  ctx.save();
  ctx.translate(p.position.x, p.position.y);
  ctx.rotate(p.angle);

  // shadow
  ctx.fillStyle = 'rgba(4, 8, 8, .18)';
  rr(ctx, -L / 2 + 4, -T / 2 + 6, L, T, T / 2);
  ctx.fill();

  // shaft
  const g = ctx.createLinearGradient(0, -T / 2, 0, T / 2);
  g.addColorStop(0, '#c08b52');
  g.addColorStop(.24, '#a2703c');
  g.addColorStop(.62, '#7c5228');
  g.addColorStop(1, '#4a2e13');
  ctx.fillStyle = g;
  rr(ctx, -L / 2, -T / 2, L, T, T / 2);
  ctx.fill();
  ctx.strokeStyle = 'rgba(38,23,9,.55)';
  ctx.lineWidth = 1.2;
  ctx.stroke();

  // grain
  ctx.save();
  rr(ctx, -L / 2, -T / 2, L, T, T / 2);
  ctx.clip();
  ctx.strokeStyle = 'rgba(64,40,16,.4)';
  ctx.lineWidth = .9;
  for (let i = 0; i < 4; i++) {
    const y = -T / 2 + 3 + i * 3.4;
    ctx.beginPath();
    ctx.moveTo(-L / 2 + 4, y);
    ctx.bezierCurveTo(-70, y - 1.6, 60, y + 1.6, L / 2 - 4, y);
    ctx.stroke();
  }
  // knots
  for (const kx of [-120, -6, 104]) {
    ctx.strokeStyle = 'rgba(54,32,11,.45)';
    ctx.lineWidth = 1.1;
    ctx.beginPath();
    ctx.ellipse(kx, 1, 7, 3.2, .1, 0, TAU);
    ctx.stroke();
    ctx.beginPath();
    ctx.ellipse(kx, 1, 3, 1.4, .1, 0, TAU);
    ctx.stroke();
  }
  // high light
  ctx.strokeStyle = 'rgba(255,222,166,.28)';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(-L / 2 + 8, -T / 2 + 3.5);
  ctx.lineTo(L / 2 - 10, -T / 2 + 3.5);
  ctx.stroke();
  ctx.restore();

  // leather grip wraps near base
  ctx.strokeStyle = 'rgba(66,39,17,.85)';
  ctx.lineWidth = 2.4;
  for (let i = 0; i < 6; i++) {
    const x = -L / 2 + 8 + i * 6;
    ctx.beginPath();
    ctx.moveTo(x, -T / 2 + 1);
    ctx.lineTo(x + 3, T / 2 - 1);
    ctx.stroke();
  }
  ctx.strokeStyle = 'rgba(156,110,62,.35)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 6; i++) {
    const x = -L / 2 + 9 + i * 6;
    ctx.beginPath();
    ctx.moveTo(x, -T / 2 + 1);
    ctx.lineTo(x + 3, T / 2 - 1);
    ctx.stroke();
  }

  // iron bands
  for (const bx of [-L / 2 + 2, -42, 74, L / 2 - 2]) {
    ctx.fillStyle = '#2d3130';
    ctx.fillRect(bx - 3.4, -T / 2 - 1.2, 6.8, T + 2.4);
    ctx.fillStyle = 'rgba(180,190,180,.26)';
    ctx.fillRect(bx - 3.4, -T / 2 - 1.2, 1.6, T + 2.4);
    ctx.fillStyle = 'rgba(8,10,10,.6)';
    ctx.beginPath();
    ctx.arc(bx, -T / 2 + 2.6, 1.1, 0, TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(bx, T / 2 - 2.6, 1.1, 0, TAU);
    ctx.fill();
  }

  // iron cap and spike at tip
  ctx.fillStyle = '#343938';
  ctx.beginPath();
  ctx.moveTo(L / 2 - 2, -T / 2 - .5);
  ctx.lineTo(L / 2 + 9, -3);
  ctx.lineTo(L / 2 + 14, 0);
  ctx.lineTo(L / 2 + 9, 3);
  ctx.lineTo(L / 2 - 2, T / 2 + .5);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(215,225,215,.35)';
  ctx.beginPath();
  ctx.moveTo(L / 2, -T / 2 + 1);
  ctx.lineTo(L / 2 + 10, -1.5);
  ctx.lineTo(L / 2 + 3, 0);
  ctx.closePath();
  ctx.fill();

  // carved sigil
  ctx.strokeStyle = 'rgba(57,35,14,.55)';
  ctx.lineWidth = 1;
  const sx = 32;
  ctx.beginPath();
  ctx.moveTo(sx - 5, -4);
  ctx.lineTo(sx, 0);
  ctx.lineTo(sx + 5, -4);
  ctx.moveTo(sx, 0);
  ctx.lineTo(sx, 4);
  ctx.stroke();

  ctx.restore();
}

function barrelFront(ctx, time, vel) {
  const tilt = clamp(vel.x * .22, -.15, .15);
  ctx.save();
  ctx.rotate(tilt);
  // back half of barrel
  const g = ctx.createLinearGradient(-34, 0, 34, 0);
  g.addColorStop(0, '#4c2f18');
  g.addColorStop(.18, '#7c5129');
  g.addColorStop(.5, '#9a6838');
  g.addColorStop(.82, '#6d4522');
  g.addColorStop(1, '#3f2712');

  // barrel silhouette (round-ish)
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(-30, -26);
  ctx.bezierCurveTo(-40, -10, -42, 22, -32, 44);
  ctx.quadraticCurveTo(0, 58, 32, 44);
  ctx.bezierCurveTo(42, 22, 40, -10, 30, -26);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(35,19,7,.65)';
  ctx.lineWidth = 1.6;
  ctx.stroke();

  // staves
  ctx.save();
  ctx.clip();
  for (let i = -3; i <= 3; i++) {
    const x = i * 9.4;
    ctx.strokeStyle = i % 2 ? 'rgba(48,28,12,.42)' : 'rgba(214,165,105,.14)';
    ctx.lineWidth = i % 2 ? 1.4 : 1;
    ctx.beginPath();
    ctx.moveTo(x * .82, -30);
    ctx.bezierCurveTo(x * 1.15, -4, x * 1.15, 24, x * .88, 56);
    ctx.stroke();
  }
  // wood grain
  ctx.strokeStyle = 'rgba(58,34,14,.25)';
  ctx.lineWidth = .8;
  for (let i = 0; i < 9; i++) {
    const y = -18 + i * 7.5;
    ctx.beginPath();
    ctx.moveTo(-40, y);
    ctx.bezierCurveTo(-14, y - 2, 14, y + 2, 40, y);
    ctx.stroke();
  }
  // barnacle specks
  ctx.fillStyle = 'rgba(180,175,150,.22)';
  for (let i = 0; i < 8; i++) {
    const a = (i * 2.399) % TAU, r = 5 + (i * 13) % 28;
    ctx.beginPath();
    ctx.arc(Math.cos(a) * r, 10 + Math.sin(a) * r * .7, 1, 0, TAU);
    ctx.fill();
  }
  ctx.restore();

  // iron hoops
  for (const y of [-19, 34]) {
    ctx.strokeStyle = '#2c2e2b';
    ctx.lineWidth = 4.4;
    ctx.beginPath();
    ctx.moveTo(-36, y);
    ctx.quadraticCurveTo(0, y + 4, 36, y);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(185,195,180,.24)';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(-35, y - 1.2);
    ctx.quadraticCurveTo(0, y + 2.8, 35, y - 1.2);
    ctx.stroke();
    // rivets
    ctx.fillStyle = 'rgba(12,13,12,.8)';
    for (let i = -2; i <= 2; i++) {
      ctx.beginPath();
      ctx.arc(i * 13, y + 2 - Math.abs(i) * .35, .9, 0, TAU);
      ctx.fill();
    }
  }

  // rope coil & small hanging anchor charm
  ctx.strokeStyle = 'rgba(190,164,116,.6)';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.arc(-19, 22, 6, -.4, 4.4);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(-20, 23, 4.4, -.2, 4.2);
  ctx.stroke();

  // barrel rim
  ctx.fillStyle = '#3a2412';
  ctx.beginPath();
  ctx.ellipse(0, -26, 30, 7, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(209,162,102,.35)';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.ellipse(0, -27, 29, 6, 0, Math.PI, TAU);
  ctx.stroke();
  ctx.restore();
}

function torso(ctx, time) {
  // striped shirt body
  const g = ctx.createLinearGradient(-18, -30, 14, -2);
  g.addColorStop(0, '#c9b18b');
  g.addColorStop(1, '#9f8767');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(-20, -14);
  ctx.quadraticCurveTo(-22, -36, -8, -40);
  ctx.lineTo(10, -40);
  ctx.quadraticCurveTo(24, -36, 22, -14);
  ctx.closePath();
  ctx.fill();
  // stripes
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(-20, -14);
  ctx.quadraticCurveTo(-22, -36, -8, -40);
  ctx.lineTo(10, -40);
  ctx.quadraticCurveTo(24, -36, 22, -14);
  ctx.closePath();
  ctx.clip();
  ctx.strokeStyle = 'rgba(122, 49, 36, .75)';
  ctx.lineWidth = 3.4;
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.moveTo(-26, -34 + i * 5.5);
    ctx.quadraticCurveTo(0, -31 + i * 5.5, 28, -34 + i * 5.5);
    ctx.stroke();
  }
  ctx.restore();
  // collar
  ctx.strokeStyle = '#6b2f24';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-8, -40);
  ctx.quadraticCurveTo(0, -34, 10, -40);
  ctx.stroke();
  // sash
  ctx.fillStyle = '#8f3429';
  ctx.save();
  ctx.translate(0, -10);
  ctx.rotate(-.12);
  ctx.fillRect(-23, -4, 46, 8);
  ctx.fillStyle = 'rgba(244,196,110,.5)';
  for (let i = -2; i <= 2; i++) ctx.fillRect(i * 9, -3, 2, 6);
  ctx.restore();
  // necklace
  ctx.strokeStyle = 'rgba(56,42,24,.8)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(-7, -40);
  ctx.quadraticCurveTo(0, -30, 8, -40);
  ctx.stroke();
  ctx.fillStyle = '#e6bd62';
  ctx.beginPath();
  ctx.moveTo(0, -30); ctx.lineTo(3, -27); ctx.lineTo(0, -24); ctx.lineTo(-3, -27);
  ctx.closePath();
  ctx.fill();
}

function head(ctx, time, lookX, lookY) {
  ctx.save();
  ctx.translate(0, -50);
  // neck
  ctx.fillStyle = '#a76b46';
  ctx.fillRect(-6, 6, 12, 10);

  // face
  const g = ctx.createRadialGradient(-6, -8, 4, 0, 0, 26);
  g.addColorStop(0, '#d9a173');
  g.addColorStop(.6, '#c1875b');
  g.addColorStop(1, '#9e633d');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(0, 0, 17, 19, 0, 0, TAU);
  ctx.fill();
  // ears
  ctx.fillStyle = '#b97b50';
  ctx.beginPath(); ctx.ellipse(-17, 0, 3.6, 6.2, -.15, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.ellipse(17, 0, 3.6, 6.2, .15, 0, TAU); ctx.fill();

  // beard
  ctx.fillStyle = '#c9c2ae';
  ctx.beginPath();
  ctx.moveTo(-17, 4);
  ctx.quadraticCurveTo(-20, 20, -9, 27);
  ctx.quadraticCurveTo(-2, 31, 0, 26);
  ctx.quadraticCurveTo(2, 31, 9, 27);
  ctx.quadraticCurveTo(20, 20, 17, 4);
  ctx.quadraticCurveTo(13, 14, 6, 15);
  ctx.quadraticCurveTo(0, 18, -6, 15);
  ctx.quadraticCurveTo(-13, 14, -17, 4);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(255,250,235,.22)';
  ctx.beginPath();
  ctx.moveTo(-6, 15); ctx.quadraticCurveTo(0, 20, 5, 15);
  ctx.quadraticCurveTo(2, 24, 0, 25); ctx.quadraticCurveTo(-3, 22, -6, 15);
  ctx.fill();
  // moustache
  ctx.fillStyle = '#bdb5a1';
  ctx.beginPath();
  ctx.moveTo(-11, 10);
  ctx.quadraticCurveTo(-4, 6, 0, 10);
  ctx.quadraticCurveTo(4, 6, 11, 10);
  ctx.quadraticCurveTo(5, 14, 0, 12);
  ctx.quadraticCurveTo(-5, 14, -11, 10);
  ctx.closePath();
  ctx.fill();

  // mouth
  ctx.strokeStyle = '#4a2018';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(-4, 17);
  ctx.quadraticCurveTo(0, 19, 4, 17);
  ctx.stroke();
  ctx.fillStyle = '#f0d27b';
  ctx.fillRect(1, 17, 2.2, 2);

  // nose
  ctx.fillStyle = '#bd7f52';
  ctx.beginPath();
  ctx.ellipse(1, 6, 5.2, 4.2, .1, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(245,200,160,.4)';
  ctx.beginPath();
  ctx.ellipse(-1, 4.5, 2.2, 1.5, .2, 0, TAU);
  ctx.fill();

  // eyes: right open, left patch
  const ex = clamp(lookX, -1, 1) * 2.6;
  const ey = clamp(lookY, -1, 1) * 1.8;
  ctx.fillStyle = '#f3e7ce';
  ctx.beginPath();
  ctx.ellipse(7, -1, 4.6, 2.8, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#2b1d12';
  ctx.beginPath();
  ctx.arc(7 + ex, -1 + ey, 1.9, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,.75)';
  ctx.beginPath();
  ctx.arc(7.6 + ex, -1.7 + ey, .55, 0, TAU);
  ctx.fill();
  // brow
  ctx.strokeStyle = '#8a7a63';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(2, -5.5);
  ctx.quadraticCurveTo(7, -7.5, 12, -5);
  ctx.stroke();

  // eyepatch
  ctx.fillStyle = '#221b15';
  ctx.beginPath();
  ctx.ellipse(-7, -1.6, 5.2, 4.2, -.2, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#2c2219';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(-11, -5);
  ctx.lineTo(-16, -10);
  ctx.moveTo(-12, 1);
  ctx.lineTo(2, 6);
  ctx.stroke();

  // scar
  ctx.strokeStyle = 'rgba(150,80,58,.55)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(9, 8);
  ctx.lineTo(13, 13);
  ctx.stroke();

  // bandana
  ctx.fillStyle = '#8e2f27';
  ctx.beginPath();
  ctx.moveTo(-18, -8);
  ctx.quadraticCurveTo(-12, -24, 0, -23);
  ctx.quadraticCurveTo(13, -24, 18, -8);
  ctx.quadraticCurveTo(9, -14, 0, -14);
  ctx.quadraticCurveTo(-9, -14, -18, -8);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(228,126,92,.25)';
  ctx.beginPath();
  ctx.moveTo(-14, -14);
  ctx.quadraticCurveTo(-4, -22, 8, -19);
  ctx.quadraticCurveTo(-2, -18, -14, -14);
  ctx.fill();
  // knot & tails
  ctx.fillStyle = '#76231d';
  ctx.beginPath();
  ctx.ellipse(17, -12, 4, 3, -.3, 0, TAU);
  ctx.fill();
  const flap = Math.sin(time * 2.2) * 2;
  ctx.beginPath();
  ctx.moveTo(18, -12);
  ctx.quadraticCurveTo(28, -10 + flap, 31, -2 + flap);
  ctx.quadraticCurveTo(24, -6, 17, -9);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(15, -10);
  ctx.quadraticCurveTo(24, -4 - flap, 22, 4 - flap);
  ctx.quadraticCurveTo(19, -1, 13, -7);
  ctx.closePath();
  ctx.fill();
  // skull pin
  ctx.fillStyle = '#e0d5b6';
  ctx.beginPath();
  ctx.arc(0, -17, 2.6, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#5a211b';
  ctx.beginPath(); ctx.arc(-.8, -17.4, .55, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.arc(1.1, -17.4, .55, 0, TAU); ctx.fill();

  // earring
  ctx.strokeStyle = '#e0b45e';
  ctx.lineWidth = 1.3;
  ctx.beginPath();
  ctx.arc(18, 5, 3.2, 0, TAU);
  ctx.stroke();
  ctx.fillStyle = '#e0b45e';
  ctx.beginPath(); ctx.arc(18, 8.4, .9, 0, TAU); ctx.fill();

  ctx.restore();
}

function drawArm(ctx, x1, y1, x2, y2, width, stripe = true) {
  ctx.strokeStyle = '#a98f6c';
  ctx.lineWidth = width;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  if (stripe) {
    ctx.strokeStyle = 'rgba(126,48,36,.55)';
    ctx.lineWidth = 2;
    const mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
    const a = Math.atan2(y2 - y1, x2 - x1);
    ctx.beginPath();
    ctx.moveTo(mx - Math.cos(a) * 2, my - Math.sin(a) * 2);
    ctx.lineTo(mx + Math.cos(a) * 2, my + Math.sin(a) * 2);
    ctx.stroke();
  }
}

function drawHookShape(ctx, x, y, angle, scale, time) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.scale(scale, scale);
  const g = ctx.createLinearGradient(-3, -6, 8, 8);
  g.addColorStop(0, '#9aa7a4');
  g.addColorStop(.35, '#d6dfda');
  g.addColorStop(.6, '#6f7a77');
  g.addColorStop(1, '#3d4645');
  ctx.strokeStyle = g;
  ctx.lineWidth = 3.4;
  ctx.lineCap = 'round';
  // shank
  ctx.beginPath();
  ctx.moveTo(-2, -10);
  ctx.lineTo(0, 5);
  ctx.stroke();
  // bill
  ctx.beginPath();
  ctx.moveTo(0, 5);
  ctx.bezierCurveTo(12, 6, 16, 16, 7, 20);
  ctx.bezierCurveTo(-2, 23, -10, 16, -8, 9);
  ctx.stroke();
  // barb
  ctx.beginPath();
  ctx.moveTo(-8, 10);
  ctx.lineTo(-13, 6);
  ctx.stroke();
  // eyelet
  ctx.strokeStyle = '#c7d2cd';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.arc(-2, -11, 2.6, 0, TAU);
  ctx.stroke();
  // glint
  const gl = .4 + Math.sin(time * 3) * .3;
  ctx.fillStyle = `rgba(255,255,255,${gl})`;
  ctx.beginPath();
  ctx.arc(3, 8, 1.1, 0, TAU);
  ctx.fill();
  ctx.restore();
}

export function drawRope(ctx, game, time) {
  const h = game.hook;
  if (!h || h.state === 'ready') return;
  const hand = game.hand();
  const end = h.pos;
  const dist = Math.hypot(end.x - hand.x, end.y - hand.y);
  const slack = h.state === 'attached' ? clamp(h.ropeLen - dist, 0, 90) : 10;
  const nx = -(end.y - hand.y) / (dist || 1);
  const ny = (end.x - hand.x) / (dist || 1);
  const mx = (hand.x + end.x) / 2 + nx * slack * .55;
  const my = (hand.y + end.y) / 2 + ny * slack * .55 + slack * .25;
  ctx.save();
  ctx.strokeStyle = 'rgba(26,22,16,.75)';
  ctx.lineWidth = 3.4;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(hand.x, hand.y);
  ctx.quadraticCurveTo(mx, my, end.x, end.y);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(196,168,116,.75)';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(hand.x, hand.y);
  ctx.quadraticCurveTo(mx, my, end.x, end.y);
  ctx.stroke();
  // twist dashes
  ctx.strokeStyle = 'rgba(90,70,40,.55)';
  ctx.lineWidth = 1;
  const steps = Math.max(4, Math.floor(dist / 16));
  for (let i = 1; i < steps; i++) {
    const t = i / steps;
    const it = 1 - t;
    const px = it * it * hand.x + 2 * it * t * mx + t * t * end.x;
    const py = it * it * hand.y + 2 * it * t * my + t * t * end.y;
    ctx.beginPath();
    ctx.moveTo(px - 2, py);
    ctx.lineTo(px + 2, py);
    ctx.stroke();
  }
  ctx.restore();
}

export function drawPirate(ctx, game, time) {
  const b = game.player;
  if (!b) return;
  const p = b.position;
  const cam = game.camera;
  const lookX = clamp((game.mouse.wx - p.x) / 180, -1, 1);
  const lookY = clamp((game.mouse.wy - p.y) / 180, -1, 1);
  const vel = b.velocity;
  const grounded = game.grounded();
  const bob = grounded ? Math.sin(time * 1.7) * .8 + Math.sin(time * 3.1) * .25 : Math.sin(time * 5) * 1.4;

  ctx.save();
  ctx.translate(p.x, p.y);

  // ground shadow
  if (grounded) {
    const sx = clamp(vel.x * 12, -10, 10);
    ctx.save();
    ctx.fillStyle = 'rgba(4,8,8,.28)';
    ctx.beginPath();
    ctx.ellipse(sx, 56, 38, 8, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(4,8,8,.12)';
    ctx.beginPath();
    ctx.ellipse(sx, 58, 54, 12, 0, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  ctx.translate(0, bob);
  torso(ctx, time);

  // left shoulder & arm toward hook hand
  const hand = { x: -25, y: 2 };
  const hookState = game.hook.state;
  if (hookState !== 'ready') {
    const ang = Math.atan2(game.hook.pos.y - p.y, game.hook.pos.x - p.x);
    hand.x = Math.cos(ang) * 30;
    hand.y = Math.sin(ang) * 24 - 4;
  }
  ctx.save();
  drawArm(ctx, -14, -20, hand.x, hand.y, 9);
  ctx.fillStyle = '#b97f54';
  ctx.beginPath();
  ctx.arc(hand.x, hand.y, 4.6, 0, TAU);
  ctx.fill();
  ctx.restore();

  // head
  head(ctx, time, lookX, lookY);

  // barrel
  barrelFront(ctx, time, vel);

  // right arm gripping the pole base
  const grip = game.shoulder();
  const gx = grip.x - p.x, gy = grip.y - p.y;
  ctx.save();
  drawArm(ctx, 16, -18, gx, gy, 10);
  // hand
  const ga = Math.atan2(gy - (-18), gx - 16);
  ctx.fillStyle = '#c1875b';
  ctx.beginPath();
  ctx.arc(gx, gy, 5.4, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(90,48,28,.5)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(gx, gy, 3, ga + .3, ga + 2.4);
  ctx.stroke();
  ctx.restore();

  // held hook when idle
  if (hookState === 'ready') {
    const sway = Math.sin(time * 1.5) * .06;
    drawHookShape(ctx, hand.x + 2, hand.y + 7, sway, .8, time);
  }

  // little glints / breath
  if (!grounded && Math.abs(vel.y) > 1.2) {
    ctx.strokeStyle = 'rgba(240,232,210,.25)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-18, -60);
    ctx.quadraticCurveTo(-26, -70, -32, -64);
    ctx.stroke();
  }

  ctx.restore();
  void cam;
}

export function drawFlyingHook(ctx, game, time) {
  const h = game.hook;
  if (!h || h.state === 'ready') return;
  if (h.state === 'attached') {
    const ang = Math.atan2(h.anchor.y - game.player.position.y, h.anchor.x - game.player.position.x);
    drawHookShape(ctx, h.pos.x, h.pos.y, ang - .4, 1, time);
    // sparks at contact
    if (Math.random() < .1) {
      ctx.fillStyle = 'rgba(255,230,170,.7)';
      ctx.beginPath();
      ctx.arc(h.pos.x + (Math.random() - .5) * 8, h.pos.y + (Math.random() - .5) * 8, 1, 0, TAU);
      ctx.fill();
    }
  } else if (h.state === 'flying') {
    const ang = Math.atan2(h.to.y - h.from.y, h.to.x - h.from.x);
    drawHookShape(ctx, h.pos.x, h.pos.y, ang + Math.sin(time * 20) * .3, .9, time);
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = 'rgba(255,220,150,.14)';
    ctx.beginPath();
    ctx.arc(h.pos.x, h.pos.y, 10, 0, TAU);
    ctx.fill();
    ctx.restore();
  } else {
    drawHookShape(ctx, h.pos.x, h.pos.y, .5, .8, time);
  }
}

/* ══════════════════════════════════════════════════════════════
   RENDERER — sky, sea, camera, particles, cursor, presentation
   ══════════════════════════════════════════════════════════════ */

import { START, SUMMIT, SEA_Y } from './level.js';
import {
  TAU, clamp, lerp, hashStr, mulberry32, SKY, mix, withA, ellipse, poly,
} from './paint.js';
import { preparePlatforms, drawIslandBackdrop, drawUndercliffs, drawPlatforms } from './terrain.js';
import { drawProp, drawChest } from './props.js';
import { drawPole, drawPirate, drawRope, drawFlyingHook } from './character.js';
import { castRay } from './level.js';

export class Renderer {
  constructor(canvas, game) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.game = game;
    this.w = window.innerWidth;
    this.h = window.innerHeight;
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.ready = false;
    this.cam = game.camera;
    this.resize();
  }

  resize() {
    this.w = window.innerWidth;
    this.h = window.innerHeight;
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.canvas.width = Math.floor(this.w * this.dpr);
    this.canvas.height = Math.floor(this.h * this.dpr);
    this.canvas.style.width = `${this.w}px`;
    this.canvas.style.height = `${this.h}px`;
    if (this.game.camera) {
      const c = this.game.camera;
      c.baseZoom = clamp(Math.max(this.w / 1750, this.h / 1100), .6, 1.12);
      if (!this.ready) c.zoom = c.baseZoom;
    }
  }

  preload() {
    if (this.ready) return;
    preparePlatforms(this.game.level);

    // stars
    const rand = mulberry32(77123);
    this.stars = [];
    for (let i = 0; i < 170; i++) {
      this.stars.push({
        x: rand(), y: rand() * .72, r: .4 + rand() * 1.7,
        a: .25 + rand() * .75, tw: rand() * TAU, big: rand() > .93,
      });
    }

    // clouds
    this.clouds = [];
    for (let i = 0; i < 26; i++) {
      this.clouds.push({
        x: -2200 + rand() * 4400,
        y: 560 - rand() * 11200,
        s: .5 + rand() * 1.3,
        a: .08 + rand() * .16,
        v: .8 + rand() * 2.4,
        warm: rand(),
      });
    }
    this.cloudSprite = this.makeCloudSprite('#ffe4c0');
    this.cloudSpriteCool = this.makeCloudSprite('#cadfe4');

    // ambient motes
    this.motes = [];
    for (let i = 0; i < 150; i++) {
      const y = 300 - rand() * 10800;
      this.motes.push({
        x: -1200 + rand() * 2400,
        y,
        s: .6 + rand() * 1.8,
        ph: rand() * TAU,
        sp: .4 + rand() * 1.2,
      });
    }

    // checkpoint flag footings
    for (const cp of this.game.level.checkpoints) {
      const hit = castRay(this.game.level.segments, cp.x, cp.y, cp.x, cp.y + 220);
      cp.footY = hit ? hit.y : cp.y + 40;
    }

    // cached fog gradients
    this.ready = true;
  }

  makeCloudSprite(color) {
    const c = document.createElement('canvas');
    c.width = 512;
    c.height = 220;
    const g = c.getContext('2d');
    const rand = mulberry32(4312);
    for (let i = 0; i < 13; i++) {
      const x = 70 + rand() * 380;
      const y = 75 + rand() * 80;
      const r = 34 + rand() * 60;
      const gr = g.createRadialGradient(x, y, 0, x, y, r);
      gr.addColorStop(0, withA(color, .5));
      gr.addColorStop(.55, withA(color, .18));
      gr.addColorStop(1, withA(color, 0));
      g.fillStyle = gr;
      g.beginPath();
      g.arc(x, y, r, 0, TAU);
      g.fill();
    }
    return c;
  }

  screenTransform() {
    const { ctx, dpr } = this;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  parallax(f = 1, mul = 1) {
    const { ctx, dpr, cam, w, h } = this;
    const z = cam.zoom * mul;
    ctx.setTransform(
      dpr * z, 0, 0, dpr * z,
      dpr * (w / 2 + cam.shakeX - cam.x * f * z),
      dpr * (h / 2 + cam.shakeY - cam.y * f * z),
    );
  }

  draw(t, dt) {
    const { ctx, w, h, game } = this;
    if (!this.ready) this.preload();
    this.screenTransform();
    ctx.clearRect(0, 0, w, h);

    const prog = game.progress ? game.progress() : 0;
    this.drawSky(prog, t);
    this.drawStars(prog, t);
    this.drawSun(prog, t);
    this.drawClouds(t, prog);
    this.drawHorizon(prog, t);

    this.parallax(1);
    drawIslandBackdrop(ctx, game, t);
    drawUndercliffs(ctx, game, this.cam, t);
    this.drawBackProps(t);
    drawPlatforms(ctx, game, this.cam, t);
    this.drawWater(t);
    this.drawFrontProps(t);
    this.drawCheckpoints(t);
    this.drawChest(t);
    this.drawRopeAndPole(t);
    this.drawPirateLayer(t);
    this.drawParticles(t);
    this.drawMotes(t);

    this.screenTransform();
    this.drawScreenEffects(t);
    this.drawCursor(t);
    this.drawDebug();
  }

  /* ── sky ───────────────────────────────────────────────── */
  drawSky(prog, t) {
    const { ctx, w, h } = this;
    const blend = clamp(prog * 1.35, 0, 1);
    const low = prog < .52 ? SKY.low : SKY.mid;
    const high = prog < .52 ? SKY.mid : SKY.high;
    const tt = prog < .52 ? prog / .52 : (prog - .52) / .48;
    const top = mix(low.top, high.top, tt);
    const mid = mix(low.mid, high.mid, tt);
    const lowc = mix(low.low, high.low, tt);
    const hor = mix(low.hor, high.hor, tt);
    const under = mix(low.under, high.under, tt);
    const g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, top);
    g.addColorStop(.3, top);
    g.addColorStop(.52, mid);
    g.addColorStop(.72, lowc);
    g.addColorStop(.86, hor);
    g.addColorStop(1, under);
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
    void blend;

    // warm atmospheric glow near the horizon
    const hz = ctx.createRadialGradient(w * .7, h * .78, 40, w * .7, h * .78, h * .75);
    hz.addColorStop(0, `rgba(255,196,116,${.18 * (1 - prog * .8)})`);
    hz.addColorStop(.5, `rgba(230,160,100,${.05 * (1 - prog * .8)})`);
    hz.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = hz;
    ctx.fillRect(0, 0, w, h);
  }

  drawStars(prog, t) {
    const { ctx, w, h } = this;
    const a = clamp((prog - .28) / .45, 0, 1);
    if (a <= .01) return;
    ctx.save();
    for (const s of this.stars) {
      const tw = .55 + .45 * Math.sin(t * 1.7 + s.tw);
      ctx.fillStyle = `rgba(225,236,236,${a * s.a * tw})`;
      ctx.beginPath();
      ctx.arc(s.x * w, s.y * h, s.r * (s.big ? 1.5 : 1), 0, TAU);
      ctx.fill();
      if (s.big) {
        ctx.strokeStyle = `rgba(220,235,240,${a * .22 * tw})`;
        ctx.lineWidth = .7;
        ctx.beginPath();
        ctx.moveTo(s.x * w - 5, s.y * h);
        ctx.lineTo(s.x * w + 5, s.y * h);
        ctx.moveTo(s.x * w, s.y * h - 5);
        ctx.lineTo(s.x * w, s.y * h + 5);
        ctx.stroke();
      }
    }
    ctx.restore();
  }

  drawSun(prog, t) {
    const { ctx, w, h } = this;
    const sunX = w * .79;
    const sunY = h * (.58 - prog * .62);
    const vis = clamp(1 - prog * .5, 0, 1);
    if (sunY > -200) {
      const warm = prog < .5;
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const R = Math.min(w, h) * .4;
      const g = ctx.createRadialGradient(sunX, sunY, 8, sunX, sunY, R);
      g.addColorStop(0, warm ? `rgba(255,220,150,${.4 * vis})` : `rgba(210,230,240,${.18 * vis})`);
      g.addColorStop(.18, warm ? `rgba(255,186,105,${.16 * vis})` : `rgba(190,220,235,${.07 * vis})`);
      g.addColorStop(.55, warm ? `rgba(230,130,80,${.05 * vis})` : `rgba(150,190,220,${.02 * vis})`);
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g;
      ctx.fillRect(sunX - R, sunY - R, R * 2, R * 2);
      const disc = ctx.createRadialGradient(sunX, sunY, 2, sunX, sunY, 42);
      disc.addColorStop(0, `rgba(255,248,219,${.95 * vis})`);
      disc.addColorStop(.5, `rgba(255,207,132,${.75 * vis})`);
      disc.addColorStop(1, `rgba(255,170,90,0)`);
      ctx.fillStyle = disc;
      ctx.beginPath();
      ctx.arc(sunX, sunY, 44, 0, TAU);
      ctx.fill();
      ctx.restore();
    }

    // moon at altitude
    if (prog > .55) {
      const ma = clamp((prog - .55) / .3, 0, 1);
      const mx = w * .17, my = h * .17;
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const rg = ctx.createRadialGradient(mx, my, 2, mx, my, 120);
      rg.addColorStop(0, `rgba(220,235,235,${.16 * ma})`);
      rg.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = rg;
      ctx.fillRect(mx - 120, my - 120, 240, 240);
      ctx.restore();
      ctx.fillStyle = `rgba(224,232,224,${.8 * ma})`;
      ctx.beginPath();
      ctx.arc(mx, my, 22, 0, TAU);
      ctx.fill();
      ctx.fillStyle = `rgba(170,185,183,${.4 * ma})`;
      ctx.beginPath(); ctx.arc(mx - 7, my - 4, 5, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.arc(mx + 6, my + 7, 3.4, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.arc(mx + 4, my - 9, 2.4, 0, TAU); ctx.fill();
    }
  }

  drawClouds(t, prog) {
    const { ctx, w, h } = this;
    const z = this.cam.zoom;
    ctx.save();
    for (const c of this.clouds) {
      const f = .18;
      const sx = (c.x - this.cam.x * f) * z * .7 + w * .5 + Math.sin(t * .02 + c.y) * 14;
      const sy = (c.y - this.cam.y * f) * z * .7 + h * .5;
      if (sy < -220 * c.s || sy > h + 220 * c.s) continue;
      if (sx < -420 * c.s || sx > w + 420 * c.s) continue;
      const alpha = c.a * (1 - prog * .2);
      ctx.globalAlpha = alpha;
      const sprite = c.warm > prog * 1.2 ? this.cloudSprite : this.cloudSpriteCool;
      const cw = 512 * c.s * .7, ch = 220 * c.s * .7;
      ctx.drawImage(sprite, sx - cw / 2, sy - ch / 2, cw, ch);
    }
    ctx.restore();
  }

  drawHorizon(prog, t) {
    const { ctx, w, h } = this;
    const z = this.cam.zoom;
    const horizon = (SEA_Y - this.cam.y * .12) * z + h / 2;
    if (horizon < h * .18 || horizon > h * 1.3) return;
    ctx.save();
    // distant haze
    const hz = ctx.createLinearGradient(0, horizon - 90, 0, horizon + 30);
    hz.addColorStop(0, 'rgba(180,190,170,0)');
    hz.addColorStop(.7, `rgba(210,190,155,${.13 * (1 - prog)})`);
    hz.addColorStop(1, 'rgba(230,196,150,0)');
    ctx.fillStyle = hz;
    ctx.fillRect(0, horizon - 90, w, 120);
    // far islands
    const drift = -this.cam.x * .02;
    for (let i = 0; i < 3; i++) {
      const ix = w * (.18 + i * .33) + drift;
      const s = [1.4, .9, 1.1][i];
      const iy = horizon + 4;
      ctx.fillStyle = i === 1 ? 'rgba(43,62,58,.55)' : 'rgba(37,56,55,.68)';
      ctx.beginPath();
      ctx.moveTo(ix - 170 * s, iy);
      ctx.bezierCurveTo(ix - 120 * s, iy - 55 * s, ix - 60 * s, iy - 34 * s, ix - 20 * s, iy - 74 * s);
      ctx.bezierCurveTo(ix + 10 * s, iy - 100 * s, ix + 34 * s, iy - 38 * s, ix + 74 * s, iy - 53 * s);
      ctx.bezierCurveTo(ix + 120 * s, iy - 32 * s, ix + 150 * s, iy - 20 * s, ix + 190 * s, iy);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }

  /* ── world layers ──────────────────────────────────────── */
  drawBackProps(t) {
    const { ctx, game } = this;
    const back = new Set(['hull', 'mast', 'sail', 'arch', 'skullgate', 'waterfall']);
    for (const p of game.level.props) {
      if (!back.has(p.type)) continue;
      drawProp(ctx, p, t, game);
    }
  }

  drawFrontProps(t) {
    const { ctx, game } = this;
    const back = new Set(['hull', 'mast', 'sail', 'arch', 'skullgate', 'waterfall']);
    for (const p of game.level.props) {
      if (back.has(p.type)) continue;
      drawProp(ctx, p, t, game);
    }
  }

  drawWater(t) {
    const { ctx } = this;
    if (this.cam.y > SEA_Y + 900) return;
    ctx.save();
    const left = -6000, right = 6000, top = SEA_Y;
    const g = ctx.createLinearGradient(0, top, 0, top + 1500);
    g.addColorStop(0, 'rgba(52,104,103,.78)');
    g.addColorStop(.12, 'rgba(30,78,84,.88)');
    g.addColorStop(.5, 'rgba(14,48,57,.94)');
    g.addColorStop(1, 'rgba(7,29,37,.98)');
    ctx.fillStyle = g;
    ctx.fillRect(left, top, right - left, 2600);
    // surface highlights
    ctx.save();
    ctx.beginPath();
    ctx.rect(left, top - 80, right - left, 260);
    ctx.clip();
    const z = this.cam.zoom;
    for (let i = 0; i < 22; i++) {
      const yy = top + i * 8;
      const a = .035 + .03 * Math.sin(i * 1.7 + t * .8);
      ctx.strokeStyle = `rgba(190,226,213,${a})`;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      const off = Math.sin(t * .4 + i) * 40;
      ctx.moveTo(left, yy + Math.sin(i) * 2);
      for (let x = left; x <= right; x += 300) {
        ctx.quadraticCurveTo(x + 150, yy + Math.sin(x * .01 + t + i) * 3, x + 300, yy + Math.sin(x * .013 + t * .7) * 2);
      }
      ctx.stroke();
    }
    // sparkle
    for (let i = 0; i < 30; i++) {
      const x = -1500 + ((i * 733) % 3000);
      const y = top + 6 + ((i * 91) % 120);
      const a = .08 + .08 * Math.sin(t * 2 + i);
      ctx.fillStyle = `rgba(240,228,180,${a})`;
      ctx.fillRect(x, y, 2, 1);
    }
    ctx.restore();
    // foam line
    ctx.strokeStyle = 'rgba(220,232,210,.25)';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    for (let x = left; x <= right; x += 100) {
      const y = top + Math.sin(x * .01 + t * 1.1) * 2.5;
      if (x === left) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.restore();
    void z;
  }

  drawCheckpoints(t) {
    const { ctx, game } = this;
    const cps = game.level.checkpoints;
    cps.forEach((cp, i) => {
      const reached = i <= game.checkpointIndex;
      const current = i === game.checkpointIndex;
      const x = cp.x, base = cp.footY ?? cp.y + 40;
      const h = 60;
      ctx.save();
      // footing shadow
      ctx.fillStyle = 'rgba(4,8,8,.25)';
      ctx.beginPath();
      ctx.ellipse(x, base + 1, 14, 4, 0, 0, TAU);
      ctx.fill();
      // post
      ctx.strokeStyle = reached ? '#5c4327' : '#3d3020';
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(x, base);
      ctx.lineTo(x, base - h);
      ctx.stroke();
      // lantern top
      ctx.fillStyle = reached ? '#f0c568' : '#8c7448';
      ctx.beginPath();
      ctx.arc(x, base - h - 2, 3.4, 0, TAU);
      ctx.fill();
      if (reached) {
        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        const g = ctx.createRadialGradient(x, base - h - 2, 0, x, base - h - 2, 36);
        g.addColorStop(0, `rgba(255,206,112,${current ? .35 : .18})`);
        g.addColorStop(1, 'rgba(255,190,80,0)');
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(x, base - h - 2, 36, 0, TAU);
        ctx.fill();
        ctx.restore();
      }
      // flag
      const wave = Math.sin(t * 3 + i * 1.7) * 2;
      ctx.fillStyle = reached ? (current ? '#e9b95a' : 'rgba(208,164,82,.7)') : 'rgba(90,84,68,.6)';
      ctx.beginPath();
      ctx.moveTo(x + 2, base - h + 4);
      ctx.quadraticCurveTo(x + 20, base - h + 6 + wave, x + 31, base - h + 10 + wave);
      ctx.lineTo(x + 28, base - h + 22);
      ctx.quadraticCurveTo(x + 18, base - h + 17 + wave, x + 2, base - h + 20);
      ctx.closePath();
      ctx.fill();
      if (reached) {
        ctx.fillStyle = 'rgba(38,26,10,.65)';
        ctx.beginPath();
        ctx.arc(x + 15, base - h + 12, 2.4, 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    });
  }

  drawChest(t) {
    const { ctx, game } = this;
    drawChest(ctx, SUMMIT.x, SUMMIT.y + 52, t, game.chestOpen || 0, 1.25);
    // treasure shine
    if (game.chestOpen > .1) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const R = 180 + Math.sin(t * 2) * 20;
      const g = ctx.createRadialGradient(SUMMIT.x, SUMMIT.y, 0, SUMMIT.x, SUMMIT.y, R);
      g.addColorStop(0, `rgba(255,220,140,${.16 * game.chestOpen})`);
      g.addColorStop(1, 'rgba(255,190,80,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(SUMMIT.x, SUMMIT.y, R, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
  }

  drawRopeAndPole(t) {
    const { ctx, game } = this;
    drawRope(ctx, game, t);
    drawPole(ctx, game, t);
  }

  drawPirateLayer(t) {
    const { ctx, game } = this;
    drawPirate(ctx, game, t);
    drawFlyingHook(ctx, game, t);
  }

  /* ── particles ─────────────────────────────────────────── */
  drawParticles(t) {
    const { ctx, game } = this;
    ctx.save();
    for (const q of game.particles) {
      const life = clamp(q.life / (q.max || 1), 0, 1);
      ctx.globalAlpha = q.type === 'gold' ? Math.min(1, life * 1.6) : Math.min(.85, life * 1.5);
      if (q.type === 'gold') {
        ctx.save();
        ctx.translate(q.x, q.y);
        ctx.rotate(q.rot || 0);
        ctx.fillStyle = q.color;
        ctx.beginPath();
        ctx.ellipse(0, 0, q.size * 1.6, q.size * .6, 0, 0, TAU);
        ctx.fill();
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha *= .4;
        ctx.beginPath();
        ctx.arc(0, 0, q.size * 2.4, 0, TAU);
        ctx.fillStyle = 'rgba(255,205,100,.4)';
        ctx.fill();
        ctx.restore();
      } else if (q.type === 'spark') {
        ctx.fillStyle = q.color;
        const a = Math.atan2(q.vy, q.vx);
        ctx.save();
        ctx.translate(q.x, q.y);
        ctx.rotate(a);
        ctx.fillRect(-q.size * 2, -q.size * .35, q.size * 3.4, q.size * .7);
        ctx.restore();
      } else {
        ctx.fillStyle = q.color;
        ctx.beginPath();
        ctx.arc(q.x, q.y, q.size * (q.type === 'splash' ? 1.2 : 1), 0, TAU);
        ctx.fill();
      }
    }
    ctx.restore();
    ctx.globalAlpha = 1;
  }

  drawMotes(t) {
    const { ctx, game } = this;
    const cam = this.cam;
    const z = cam.zoom;
    const vw = this.w / z, vh = this.h / z;
    const l = cam.x - vw / 2, r = cam.x + vw / 2, tp = cam.y - vh / 2, bt = cam.y + vh / 2;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const m of this.motes) {
      if (m.x < l - 40 || m.x > r + 40 || m.y < tp - 40 || m.y > bt + 40) continue;
      const zone = game.level.zoneAt(m.y);
      let color, a;
      if (zone.id === 'jungle') { color = '190,235,120'; a = .5; }
      else if (zone.id === 'summit') { color = '255,215,120'; a = .55; }
      else if (zone.id === 'ruins') { color = '215,205,175'; a = .28; }
      else if (zone.id === 'wreck') { color = '240,190,120'; a = .3; }
      else { color = '235,235,215'; a = .28; }
      const wob = Math.sin(t * m.sp + m.ph) * 14;
      const wob2 = Math.cos(t * m.sp * .7 + m.ph) * 10;
      const x = m.x + wob, y = m.y + wob2;
      const alpha = a * (.55 + .45 * Math.sin(t * 2.2 + m.ph));
      const g = ctx.createRadialGradient(x, y, 0, x, y, m.s * 5);
      g.addColorStop(0, `rgba(${color},${alpha})`);
      g.addColorStop(1, `rgba(${color},0)`);
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(x, y, m.s * 5, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }

  /* ── screen space ──────────────────────────────────────── */
  drawScreenEffects(t) {
    const { ctx, w, h, game } = this;

    if (game.splashFlash > 0) {
      const a = game.splashFlash;
      const g = ctx.createRadialGradient(w / 2, h * .7, 20, w / 2, h * .7, h);
      g.addColorStop(0, `rgba(170,225,215,${.28 * a})`);
      g.addColorStop(1, `rgba(40,95,105,${.55 * a})`);
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, w, h);
    }

    if (game.mode === 'ending') {
      const a = clamp(game.endTimer / 2.6, 0, 1) * .4;
      const g = ctx.createRadialGradient(w / 2, h * .55, 20, w / 2, h * .55, h * .8);
      g.addColorStop(0, `rgba(255,220,140,${a * .3})`);
      g.addColorStop(1, `rgba(90,55,15,${a * .35})`);
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, w, h);
    }

    // subtle top and bottom letterbox shading
    const topG = ctx.createLinearGradient(0, 0, 0, 110);
    topG.addColorStop(0, 'rgba(3,9,10,.36)');
    topG.addColorStop(1, 'rgba(3,9,10,0)');
    ctx.fillStyle = topG;
    ctx.fillRect(0, 0, w, 110);
    const botG = ctx.createLinearGradient(0, h - 150, 0, h);
    botG.addColorStop(0, 'rgba(3,9,10,0)');
    botG.addColorStop(1, 'rgba(3,9,10,.42)');
    ctx.fillStyle = botG;
    ctx.fillRect(0, h - 150, w, 150);

    // warm/cool grade
    ctx.save();
    ctx.globalCompositeOperation = 'soft-light';
    const grade = ctx.createLinearGradient(0, 0, 0, h);
    const prog = game.progress ? game.progress() : 0;
    grade.addColorStop(0, `rgba(${prog > .5 ? '70,110,160' : '80,150,150'},.12)`);
    grade.addColorStop(1, 'rgba(210,150,80,.12)');
    ctx.fillStyle = grade;
    ctx.fillRect(0, 0, w, h);
    ctx.restore();
    void t;
  }

  drawCursor(t) {
    const { ctx, game } = this;
    if (game.mode !== 'playing') return;
    const x = game.mouse.x, y = game.mouse.y;
    const grip = game.grip;
    const attached = game.hook.state === 'attached';
    const col = attached ? 'rgba(255,216,130,.9)' : 'rgba(235,214,176,.75)';
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(t * .5);
    ctx.strokeStyle = col;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(0, 0, grip ? 7 : 9, .3, 1.1);
    ctx.arc(0, 0, grip ? 7 : 9, 1.8, 2.6);
    ctx.arc(0, 0, grip ? 7 : 9, 3.3, 4.1);
    ctx.arc(0, 0, grip ? 7 : 9, 4.8, 5.6);
    ctx.stroke();
    ctx.rotate(-t * .5);
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.arc(0, 0, grip ? 2.2 : 1.3, 0, TAU);
    ctx.fill();
    if (attached) {
      ctx.strokeStyle = 'rgba(255,210,120,.28)';
      ctx.beginPath();
      ctx.arc(0, 0, 15 + Math.sin(t * 4) * 2, 0, TAU);
      ctx.stroke();
    }
    ctx.restore();

    // faint pole reach marker
    const pole = game.pole;
    if (pole) {
      const tip = game.poleTip();
      const sx = (tip.x - this.cam.x) * this.cam.zoom + this.w / 2 + this.cam.shakeX;
      const sy = (tip.y - this.cam.y) * this.cam.zoom + this.h / 2 + this.cam.shakeY;
      ctx.save();
      ctx.translate(sx, sy);
      ctx.rotate(Math.PI / 4);
      ctx.strokeStyle = 'rgba(230,190,110,.25)';
      ctx.lineWidth = 1;
      ctx.strokeRect(-3, -3, 6, 6);
      ctx.restore();
    }
  }

  drawDebug() {
    const g = this.game;
    if (!g.debug) return;
    const { ctx } = this;
    const p = g.player.position;
    const lines = [
      `mode ${g.mode}  alt ${g.altitude()}m  prog ${(g.progress() * 100).toFixed(1)}%`,
      `player ${p.x.toFixed(0)}, ${p.y.toFixed(0)}  v ${g.player.velocity.x.toFixed(2)}, ${g.player.velocity.y.toFixed(2)}`,
      `pole a ${g.pole.angle.toFixed(2)} av ${g.pole.angularVelocity.toFixed(4)} tq ${(g.pole.torque || 0).toFixed(2)}`,
      `hook ${g.hook.state} len ${g.hook.ropeLen.toFixed(0)}  cam ${this.cam.zoom.toFixed(2)}`,
      `cp ${g.checkpointIndex}  falls ${g.stats.falls}`,
    ];
    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,.55)';
    ctx.fillRect(12, 86, 330, 96);
    ctx.fillStyle = '#b9e6c8';
    ctx.font = '11px monospace';
    lines.forEach((l, i) => ctx.fillText(l, 22, 104 + i * 16));
    ctx.restore();
  }
}

