export function drawUndercliffs(ctx, game, cam, time) {
  for (const p of game.level.platforms) {
    if (p.ship) continue;
    const beach = p.id === 'beach';
    const depth = beach ? 760 : 170 + p.seed * 230;
    const rand = mulberry32(hashStr(p.id + 'cliff'));
    const nx = p.nx, ny = p.ny;
    const palettes = {
      sand: ['#6d5433', '#4b3822', '#332617'],
      wood: ['#4a3420', '#332315', '#21160c'],
      deck: ['#4a3420', '#332315', '#21160c'],
      rock: ['#42403a', '#302e28', '#211f1b'],
      moss: ['#38452e', '#293521', '#1c2618'],
      stone: ['#4a4840', '#36342d', '#24231e'],
      gold: ['#4b3d21', '#342a16', '#221b0e'],
    };
    const pal = palettes[p.type] || palettes.rock;
    const x1 = p.x1, y1 = p.y1, x2 = p.x2, y2 = p.y2;

    const dA = depth * (.6 + rand() * .3);
    const dB = depth * (.85 + rand() * .35);
    const dC = depth * (.55 + rand() * .3);
    const midx = (x1 + x2) / 2, midy = (y1 + y2) / 2;
    const left = { x: x1 + nx * dC + (rand() - .5) * 30, y: y1 + ny * dC };
    const middle = { x: midx + nx * dB, y: midy + ny * dB + (rand() - .5) * 24 };
    const right = { x: x2 + nx * dA + (rand() - .5) * 30, y: y2 + ny * dA };

    const pts = [{ x: x1 + 2, y: y1 + 3 }, { x: x2 - 2, y: y2 + 3 }, right, middle, left];
    poly(ctx, pts);
    const g = ctx.createLinearGradient(0, Math.min(y1, y2), 0, Math.max(y1, y2) + ny * depth);
    g.addColorStop(0, pal[0]);
    g.addColorStop(.4, pal[1]);
    g.addColorStop(1, pal[2]);
    ctx.fillStyle = g;
    ctx.fill();

    ctx.save();
    poly(ctx, pts);
    ctx.clip();
    // facets
    for (let i = 0; i < 4; i++) {
      const fx = p.cx + (rand() - .5) * p.len;
      const fy = (y1 + y2) / 2 + ny * depth * (.2 + rand() * .5);
      const fw = 18 + rand() * 46;
      const fh = 40 + rand() * 90;
      ctx.fillStyle = i % 2 ? 'rgba(255,240,200,.028)' : 'rgba(0,0,0,.15)';
      ctx.beginPath();
      ctx.moveTo(fx, fy);
      ctx.lineTo(fx + fw, fy + fh * .3);
      ctx.lineTo(fx + fw * .4, fy + fh);
      ctx.lineTo(fx - fw * .5, fy + fh * .55);
      ctx.closePath();
      ctx.fill();
    }
    // strata
    ctx.strokeStyle = 'rgba(0,0,0,.16)';
    ctx.lineWidth = 2;
    for (let i = 1; i < 5; i++) {
      const yy = (y1 + ny * depth * (i / 5));
      ctx.beginPath();
      ctx.moveTo(p.cx - p.len, yy);
      ctx.quadraticCurveTo(p.cx, yy + 12, p.cx + p.len, yy - 6);
      ctx.stroke();
    }
    ctx.restore();

    // edge highlight and boulders
    ctx.strokeStyle = 'rgba(255,230,180,.06)';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(left.x, left.y);
    ctx.lineTo(x1 + 2, y1 + 3);
    ctx.stroke();

    if (!beach && p.type !== 'wood' && p.type !== 'deck') {
      for (let i = 0; i < 3; i++) {
        const bx = p.cx + (rand() - .5) * p.len * .8;
        const by = middle.y - rand() * 30;
