    if (p.type === 'moss' || p.type === 'stone') {
      const r2 = mulberry32(hashStr(p.id + 'roots'));
      const n = p.len > 120 ? 6 : 3;
      for (let i = 0; i < n; i++) {
        const rx = p.x1 + r2() * (p.x2 - p.x1);
        const len = 40 + r2() * 170;
        ctx.strokeStyle = p.type === 'moss' ? 'rgba(70,92,52,.72)' : 'rgba(60,72,52,.5)';
        ctx.lineWidth = 1.3;
        ctx.beginPath();
        ctx.moveTo(rx, p.y1 + 2);
        ctx.bezierCurveTo(rx + 10, p.y1 + len * .35, rx - 8, p.y1 + len * .7, rx + 4, p.y1 + len);
        ctx.stroke();
        if (p.type === 'moss' && len > 90) {
