/** The great sea-stack behind the whole climb. */
export function drawSeaStack(ctx, game, time) {
  if (!game._stack) {
    const rand = mulberry32(91827);
    const pts = [];
    for (let y = 560; y >= -10600; y -= 90) {
      const k = clamp((560 - y) / 11160, 0, 1);
      const ease = k * k * (3 - 2 * k);
      const cx = 120 + 190 * Math.sin(y / 1250) + 90 * Math.sin(y / 430 + 1.4);
      const w = lerp(2050, 640, ease) + Math.sin(y / 210) * 46 + (rand() - .5) * 60;
      const jag = (rand() - .5) * 34;
      pts.push({ y, cx, w, left: cx - w / 2 + jag, right: cx + w / 2 - jag });
    }
    game._stack = pts;
    game._stackFar = pts.map((p, i) => ({
      y: p.y + 40,
      left: p.left - 170 - Math.sin(i * 1.7) * 60,
      right: p.right + 220 + Math.cos(i * 2.1) * 70,
    }));
  }
  const pts = game._stack;
  const far = game._stackFar;

  // far silhouette
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(far[0].left, far[0].y);
  for (let i = 1; i < far.length; i++) ctx.lineTo(far[i].left, far[i].y);
  for (let i = far.length - 1; i >= 0; i--) ctx.lineTo(far[i].right, far[i].y);
  ctx.closePath();
  ctx.fillStyle = 'rgba(71, 96, 94, .34)';
  ctx.fill();
  ctx.restore();

  // main mass
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(pts[0].left, pts[0].y);
  for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].left, pts[i].y);
  for (let i = pts.length - 1; i >= 0; i--) ctx.lineTo(pts[i].right, pts[i].y);
  ctx.closePath();
  const g = ctx.createLinearGradient(-700, 500, 900, -10600);
  g.addColorStop(0, '#4d4631');
  g.addColorStop(.18, '#454b38');
  g.addColorStop(.34, '#39473b');
  g.addColorStop(.52, '#354147');
  g.addColorStop(.72, '#3a3d44');
  g.addColorStop(.9, '#43434a');
  g.addColorStop(1, '#4b4a4f');
  ctx.fillStyle = g;
  ctx.fill();

  ctx.save();
  ctx.clip();
  const rand = mulberry32(5522);
  // broad facets
  for (let i = 0; i < 80; i++) {
    const y = 480 - rand() * 11000;
    const x = -850 + rand() * 1750;
    const w = 80 + rand() * 330;
    const h = 120 + rand() * 520;
    ctx.fillStyle = i % 3 === 0 ? 'rgba(238,225,190,.045)' : (i % 3 === 1 ? 'rgba(10,15,14,.14)' : 'rgba(90,110,95,.05)');
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + w, y + h * .12);
    ctx.lineTo(x + w * .72, y + h);
    ctx.lineTo(x - w * .16, y + h * .6);
    ctx.closePath();
    ctx.fill();
  }
  // strata
  for (let i = 0; i < 60; i++) {
    const y = 500 - i * 190;
    ctx.strokeStyle = `rgba(16,20,18,${.05 + rand() * .08})`;
    ctx.lineWidth = 2 + rand() * 8;
    ctx.beginPath();
    ctx.moveTo(-900, y);
    ctx.bezierCurveTo(-300, y + 40, 400, y - 40, 1200, y + 20);
    ctx.stroke();
  }
  // moss bands
  for (const [ya, yb, col] of [[-2300, -5200, '64,88,52'], [-5200, -8000, '58,74,52'], [-8000, -10300, '74,76,66']]) {
    for (let i = 0; i < 55; i++) {
      const y = lerp(ya, yb, rand());
      const x = -800 + rand() * 1700;
      const r = 8 + rand() * 40;
      ctx.fillStyle = `rgba(${col},${.06 + rand() * .1})`;
      ctx.beginPath();
      ctx.ellipse(x, y, r, r * .4, rand() * 3, 0, TAU);
      ctx.fill();
    }
  }
  // sunlit left rim
  const rim = ctx.createLinearGradient(-700, 0, 0, 0);
  rim.addColorStop(0, 'rgba(255,226,170,.13)');
  rim.addColorStop(1, 'rgba(255,226,170,0)');
  ctx.fillStyle = rim;
  ctx.fillRect(-900, -10600, 900, 11200);
  // top fog
  const fog = ctx.createLinearGradient(0, -10600, 0, -8000);
  fog.addColorStop(0, 'rgba(160,170,175,.18)');
  fog.addColorStop(1, 'rgba(160,170,175,0)');
  ctx.fillStyle = fog;
  ctx.fillRect(-1000, -10600, 2400, 2700);
  ctx.restore();

  // near left edge highlight
  ctx.strokeStyle = 'rgba(255,226,175,.12)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(pts[0].left, pts[0].y);
  for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].left, pts[i].y);
  ctx.stroke();

