180:     g.addColorStop(.52, mid);
181:     g.addColorStop(.72, lowc);
182:     g.addColorStop(.86, hor);
183:     g.addColorStop(1, under);
184:     ctx.fillStyle = g;
185:     ctx.fillRect(0, 0, w, h);
186:     void blend;
187: 
188:     // warm atmospheric glow near the horizon
189:     const hz = ctx.createRadialGradient(w * .7, h * .78, 40, w * .7, h * .78, h * .75);
190:     hz.addColorStop(0, `rgba(255,196,116,${.3 * (1 - prog * .8)})`);
191:     hz.addColorStop(.5, `rgba(230,160,100,${.1 * (1 - prog * .8)})`);
192:     hz.addColorStop(1, 'rgba(0,0,0,0)');
193:     ctx.fillStyle = hz;
194:     ctx.fillRect(0, 0, w, h);
