197:   drawStars(prog, t) {
198:     const { ctx, w, h } = this;
199:     const a = clamp((prog - .28) / .45, 0, 1);
200:     if (a <= .01) return;
201:     ctx.save();
202:     for (const s of this.stars) {
203:       const tw = .55 + .45 * Math.sin(t * 1.7 + s.tw);
204:       ctx.fillStyle = `rgba(225,236,236,${a * s.a * tw})`;
205:       ctx.beginPath();
206:       ctx.arc(s.x * w, s.y * h, s.r * (s.big ? 1.5 : 1), 0, TAU);
207:       ctx.fill();
208:       if (s.big) {
209:         ctx.strokeStyle = `rgba(220,235,240,${a * .22 * tw})`;
210:         ctx.lineWidth = .7;
211:         ctx.beginPath();
212:         ctx.moveTo(s.x * w - 5, s.y * h);
213:         ctx.lineTo(s.x * w + 5, s.y * h);
214:         ctx.moveTo(s.x * w, s.y * h - 5);
215:         ctx.lineTo(s.x * w, s.y * h + 5);
216:         ctx.stroke();
217:       }
218:     }
219:     ctx.restore();
220:   }
