222:   drawSun(prog, t) {
223:     const { ctx, w, h } = this;
224:     const sunX = w * .79;
225:     const sunY = h * (.4 - prog * .48);
226:     const vis = clamp(1 - prog * .5, 0, 1);
227:     if (sunY > -200) {
228:       const warm = prog < .5;
229:       ctx.save();
230:       ctx.globalCompositeOperation = 'lighter';
231:       const R = Math.min(w, h) * .4;
232:       const g = ctx.createRadialGradient(sunX, sunY, 8, sunX, sunY, R);
233:       g.addColorStop(0, warm ? `rgba(255,220,150,${.4 * vis})` : `rgba(210,230,240,${.18 * vis})`);
234:       g.addColorStop(.18, warm ? `rgba(255,186,105,${.16 * vis})` : `rgba(190,220,235,${.07 * vis})`);
235:       g.addColorStop(.55, warm ? `rgba(230,130,80,${.05 * vis})` : `rgba(150,190,220,${.02 * vis})`);
236:       g.addColorStop(1, 'rgba(0,0,0,0)');
237:       ctx.fillStyle = g;
238:       ctx.fillRect(sunX - R, sunY - R, R * 2, R * 2);
239:       const disc = ctx.createRadialGradient(sunX, sunY, 2, sunX, sunY, 42);
240:       disc.addColorStop(0, `rgba(255,248,219,${.95 * vis})`);
241:       disc.addColorStop(.5, `rgba(255,207,132,${.75 * vis})`);
242:       disc.addColorStop(1, `rgba(255,170,90,0)`);
243:       ctx.fillStyle = disc;
244:       ctx.beginPath();
245:       ctx.arc(sunX, sunY, 44, 0, TAU);
246:       ctx.fill();
247:       ctx.restore();
248:     }
249: 
250:     // moon at altitude
251:     if (prog > .55) {
252:       const ma = clamp((prog - .55) / .3, 0, 1);
253:       const mx = w * .17, my = h * .17;
254:       ctx.save();
255:       ctx.globalCompositeOperation = 'lighter';
256:       const rg = ctx.createRadialGradient(mx, my, 2, mx, my, 120);
257:       rg.addColorStop(0, `rgba(220,235,235,${.16 * ma})`);
258:       rg.addColorStop(1, 'rgba(0,0,0,0)');
259:       ctx.fillStyle = rg;
260:       ctx.fillRect(mx - 120, my - 120, 240, 240);
261:       ctx.restore();
262:       ctx.fillStyle = `rgba(224,232,224,${.8 * ma})`;
263:       ctx.beginPath();
264:       ctx.arc(mx, my, 22, 0, TAU);
265:       ctx.fill();
266:       ctx.fillStyle = `rgba(170,185,183,${.4 * ma})`;
267:       ctx.beginPath(); ctx.arc(mx - 7, my - 4, 5, 0, TAU); ctx.fill();
268:       ctx.beginPath(); ctx.arc(mx + 6, my + 7, 3.4, 0, TAU); ctx.fill();
269:       ctx.beginPath(); ctx.arc(mx + 4, my - 9, 2.4, 0, TAU); ctx.fill();
270:     }
271:   }
