273:   drawClouds(t, prog) {
274:     const { ctx, w, h } = this;
275:     const z = this.cam.zoom;
276:     ctx.save();
277:     for (const c of this.clouds) {
278:       const f = .18;
279:       const sx = (c.x - this.cam.x * f) * z * .7 + w * .5 + Math.sin(t * .02 + c.y) * 14;
280:       const sy = (c.y - this.cam.y * f) * z * .7 + h * .5;
281:       if (sy < -220 * c.s || sy > h + 220 * c.s) continue;
282:       if (sx < -420 * c.s || sx > w + 420 * c.s) continue;
283:       const alpha = c.a * (1 - prog * .2);
284:       ctx.globalAlpha = alpha;
285:       const sprite = c.warm > prog * 1.2 ? this.cloudSprite : this.cloudSpriteCool;
286:       const cw = 512 * c.s * .7, ch = 220 * c.s * .7;
287:       ctx.drawImage(sprite, sx - cw / 2, sy - ch / 2, cw, ch);
288:     }
289:     ctx.restore();
290:   }
