292:   drawHorizon(prog, t) {
293:     const { ctx, w, h } = this;
294:     const z = this.cam.zoom;
295:     const horizon = (SEA_Y - this.cam.y * .12) * z + h / 2;
296:     if (horizon < h * .18 || horizon > h * 1.3) return;
297:     ctx.save();
298:     // distant haze
299:     const hz = ctx.createLinearGradient(0, horizon - 90, 0, horizon + 30);
300:     hz.addColorStop(0, 'rgba(180,190,170,0)');
301:     hz.addColorStop(.7, `rgba(210,190,155,${.13 * (1 - prog)})`);
302:     hz.addColorStop(1, 'rgba(230,196,150,0)');
303:     ctx.fillStyle = hz;
304:     ctx.fillRect(0, horizon - 90, w, 120);
305:     // far islands
306:     const drift = -this.cam.x * .02;
307:     for (let i = 0; i < 3; i++) {
308:       const ix = w * (.18 + i * .33) + drift;
309:       const s = [1.4, .9, 1.1][i];
310:       const iy = horizon + 4;
311:       ctx.fillStyle = i === 1 ? 'rgba(43,62,58,.55)' : 'rgba(37,56,55,.68)';
312:       ctx.beginPath();
313:       ctx.moveTo(ix - 170 * s, iy);
314:       ctx.bezierCurveTo(ix - 120 * s, iy - 55 * s, ix - 60 * s, iy - 34 * s, ix - 20 * s, iy - 74 * s);
315:       ctx.bezierCurveTo(ix + 10 * s, iy - 100 * s, ix + 34 * s, iy - 38 * s, ix + 74 * s, iy - 53 * s);
316:       ctx.bezierCurveTo(ix + 120 * s, iy - 32 * s, ix + 150 * s, iy - 20 * s, ix + 190 * s, iy);
317:       ctx.closePath();
318:       ctx.fill();
319:     }
320:     ctx.restore();
321:   }
