342:   drawWater(t) {
343:     const { ctx } = this;
344:     if (this.cam.y > SEA_Y + 900) return;
345:     ctx.save();
346:     const left = -6000, right = 6000, top = SEA_Y;
347:     const g = ctx.createLinearGradient(0, top, 0, top + 1500);
348:     g.addColorStop(0, 'rgba(52,104,103,.78)');
349:     g.addColorStop(.12, 'rgba(30,78,84,.88)');
350:     g.addColorStop(.5, 'rgba(14,48,57,.94)');
351:     g.addColorStop(1, 'rgba(7,29,37,.98)');
352:     ctx.fillStyle = g;
353:     ctx.fillRect(left, top, right - left, 2600);
354:     // surface highlights
355:     ctx.save();
356:     ctx.beginPath();
357:     ctx.rect(left, top - 80, right - left, 260);
358:     ctx.clip();
359:     const z = this.cam.zoom;
360:     for (let i = 0; i < 22; i++) {
361:       const yy = top + i * 8;
362:       const a = .035 + .03 * Math.sin(i * 1.7 + t * .8);
363:       ctx.strokeStyle = `rgba(190,226,213,${a})`;
364:       ctx.lineWidth = 1.2;
365:       ctx.beginPath();
366:       const off = Math.sin(t * .4 + i) * 40;
367:       ctx.moveTo(left, yy + Math.sin(i) * 2);
368:       for (let x = left; x <= right; x += 300) {
369:         ctx.quadraticCurveTo(x + 150, yy + Math.sin(x * .01 + t + i) * 3, x + 300, yy + Math.sin(x * .013 + t * .7) * 2);
370:       }
371:       ctx.stroke();
372:     }
373:     // sparkle
374:     for (let i = 0; i < 30; i++) {
375:       const x = -1500 + ((i * 733) % 3000);
376:       const y = top + 6 + ((i * 91) % 120);
377:       const a = .08 + .08 * Math.sin(t * 2 + i);
378:       ctx.fillStyle = `rgba(240,228,180,${a})`;
379:       ctx.fillRect(x, y, 2, 1);
380:     }
381:     ctx.restore();
382:     // foam line
383:     ctx.strokeStyle = 'rgba(220,232,210,.25)';
384:     ctx.lineWidth = 1.4;
385:     ctx.beginPath();
386:     for (let x = left; x <= right; x += 100) {
387:       const y = top + Math.sin(x * .01 + t * 1.1) * 2.5;
388:       if (x === left) ctx.moveTo(x, y); else ctx.lineTo(x, y);
389:     }
390:     ctx.stroke();
391:     ctx.restore();
392:     void z;
393:   }
