395:   drawCheckpoints(t) {
396:     const { ctx, game } = this;
397:     const cps = game.level.checkpoints;
398:     cps.forEach((cp, i) => {
399:       const reached = i <= game.checkpointIndex;
400:       const current = i === game.checkpointIndex;
401:       const x = cp.x, base = cp.footY ?? cp.y + 40;
402:       const h = 60;
403:       ctx.save();
404:       // footing shadow
405:       ctx.fillStyle = 'rgba(4,8,8,.25)';
406:       ctx.beginPath();
407:       ctx.ellipse(x, base + 1, 14, 4, 0, 0, TAU);
408:       ctx.fill();
409:       // post
410:       ctx.strokeStyle = reached ? '#5c4327' : '#3d3020';
411:       ctx.lineWidth = 4;
412:       ctx.beginPath();
413:       ctx.moveTo(x, base);
414:       ctx.lineTo(x, base - h);
415:       ctx.stroke();
416:       // lantern top
417:       ctx.fillStyle = reached ? '#f0c568' : '#8c7448';
418:       ctx.beginPath();
419:       ctx.arc(x, base - h - 2, 3.4, 0, TAU);
420:       ctx.fill();
421:       if (reached) {
422:         ctx.save();
423:         ctx.globalCompositeOperation = 'lighter';
424:         const g = ctx.createRadialGradient(x, base - h - 2, 0, x, base - h - 2, 36);
425:         g.addColorStop(0, `rgba(255,206,112,${current ? .35 : .18})`);
426:         g.addColorStop(1, 'rgba(255,190,80,0)');
427:         ctx.fillStyle = g;
428:         ctx.beginPath();
429:         ctx.arc(x, base - h - 2, 36, 0, TAU);
430:         ctx.fill();
431:         ctx.restore();
432:       }
433:       // flag
434:       const wave = Math.sin(t * 3 + i * 1.7) * 2;
435:       ctx.fillStyle = reached ? (current ? '#e9b95a' : 'rgba(208,164,82,.7)') : 'rgba(90,84,68,.6)';
436:       ctx.beginPath();
437:       ctx.moveTo(x + 2, base - h + 4);
438:       ctx.quadraticCurveTo(x + 20, base - h + 6 + wave, x + 31, base - h + 10 + wave);
439:       ctx.lineTo(x + 28, base - h + 22);
440:       ctx.quadraticCurveTo(x + 18, base - h + 17 + wave, x + 2, base - h + 20);
441:       ctx.closePath();
442:       ctx.fill();
443:       if (reached) {
444:         ctx.fillStyle = 'rgba(38,26,10,.65)';
445:         ctx.beginPath();
446:         ctx.arc(x + 15, base - h + 12, 2.4, 0, TAU);
447:         ctx.fill();
448:       }
449:       ctx.restore();
450:     });
451:   }
