485:   drawParticles(t) {
486:     const { ctx, game } = this;
487:     ctx.save();
488:     for (const q of game.particles) {
489:       const life = clamp(q.life / (q.max || 1), 0, 1);
490:       ctx.globalAlpha = q.type === 'gold' ? Math.min(1, life * 1.6) : Math.min(.85, life * 1.5);
491:       if (q.type === 'gold') {
492:         ctx.save();
493:         ctx.translate(q.x, q.y);
494:         ctx.rotate(q.rot || 0);
495:         ctx.fillStyle = q.color;
496:         ctx.beginPath();
497:         ctx.ellipse(0, 0, q.size * 1.6, q.size * .6, 0, 0, TAU);
498:         ctx.fill();
499:         ctx.globalCompositeOperation = 'lighter';
500:         ctx.globalAlpha *= .4;
501:         ctx.beginPath();
502:         ctx.arc(0, 0, q.size * 2.4, 0, TAU);
503:         ctx.fillStyle = 'rgba(255,205,100,.4)';
504:         ctx.fill();
505:         ctx.restore();
506:       } else if (q.type === 'spark') {
507:         ctx.fillStyle = q.color;
508:         const a = Math.atan2(q.vy, q.vx);
509:         ctx.save();
510:         ctx.translate(q.x, q.y);
511:         ctx.rotate(a);
512:         ctx.fillRect(-q.size * 2, -q.size * .35, q.size * 3.4, q.size * .7);
513:         ctx.restore();
514:       } else {
515:         ctx.fillStyle = q.color;
516:         ctx.beginPath();
517:         ctx.arc(q.x, q.y, q.size * (q.type === 'splash' ? 1.2 : 1), 0, TAU);
518:         ctx.fill();
519:       }
520:     }
521:     ctx.restore();
522:     ctx.globalAlpha = 1;
