525:   drawMotes(t) {
526:     const { ctx, game } = this;
527:     const cam = this.cam;
528:     const z = cam.zoom;
529:     const vw = this.w / z, vh = this.h / z;
530:     const l = cam.x - vw / 2, r = cam.x + vw / 2, tp = cam.y - vh / 2, bt = cam.y + vh / 2;
531:     ctx.save();
532:     ctx.globalCompositeOperation = 'lighter';
533:     for (const m of this.motes) {
534:       if (m.x < l - 40 || m.x > r + 40 || m.y < tp - 40 || m.y > bt + 40) continue;
535:       const zone = game.level.zoneAt(m.y);
536:       let color, a;
537:       if (zone.id === 'jungle') { color = '190,235,120'; a = .5; }
538:       else if (zone.id === 'summit') { color = '255,215,120'; a = .55; }
539:       else if (zone.id === 'ruins') { color = '215,205,175'; a = .28; }
540:       else if (zone.id === 'wreck') { color = '240,190,120'; a = .3; }
541:       else { color = '235,235,215'; a = .28; }
542:       const wob = Math.sin(t * m.sp + m.ph) * 14;
543:       const wob2 = Math.cos(t * m.sp * .7 + m.ph) * 10;
544:       const x = m.x + wob, y = m.y + wob2;
545:       const alpha = a * (.55 + .45 * Math.sin(t * 2.2 + m.ph));
546:       const g = ctx.createRadialGradient(x, y, 0, x, y, m.s * 5);
547:       g.addColorStop(0, `rgba(${color},${alpha})`);
548:       g.addColorStop(1, `rgba(${color},0)`);
549:       ctx.fillStyle = g;
550:       ctx.beginPath();
551:       ctx.arc(x, y, m.s * 5, 0, TAU);
552:       ctx.fill();
553:     }
554:     ctx.restore();
555:   }
