604:   drawCursor(t) {
605:     const { ctx, game } = this;
606:     if (game.mode !== 'playing') return;
607:     const x = game.mouse.x, y = game.mouse.y;
608:     const grip = game.grip;
609:     const attached = game.hook.state === 'attached';
610:     const col = attached ? 'rgba(255,216,130,.9)' : 'rgba(235,214,176,.75)';
611:     ctx.save();
612:     ctx.translate(x, y);
613:     ctx.rotate(t * .5);
614:     ctx.strokeStyle = col;
615:     ctx.lineWidth = 1;
616:     ctx.beginPath();
617:     ctx.arc(0, 0, grip ? 7 : 9, .3, 1.1);
618:     ctx.arc(0, 0, grip ? 7 : 9, 1.8, 2.6);
619:     ctx.arc(0, 0, grip ? 7 : 9, 3.3, 4.1);
620:     ctx.arc(0, 0, grip ? 7 : 9, 4.8, 5.6);
621:     ctx.stroke();
622:     ctx.rotate(-t * .5);
623:     ctx.fillStyle = col;
624:     ctx.beginPath();
625:     ctx.arc(0, 0, grip ? 2.2 : 1.3, 0, TAU);
626:     ctx.fill();
627:     if (attached) {
628:       ctx.strokeStyle = 'rgba(255,210,120,.28)';
629:       ctx.beginPath();
630:       ctx.arc(0, 0, 15 + Math.sin(t * 4) * 2, 0, TAU);
631:       ctx.stroke();
632:     }
633:     ctx.restore();
634: 
635:     // faint pole reach marker
636:     const pole = game.pole;
637:     if (pole) {
638:       const tip = game.poleTip();
639:       const sx = (tip.x - this.cam.x) * this.cam.zoom + this.w / 2 + this.cam.shakeX;
640:       const sy = (tip.y - this.cam.y) * this.cam.zoom + this.h / 2 + this.cam.shakeY;
641:       ctx.save();
642:       ctx.translate(sx, sy);
643:       ctx.rotate(Math.PI / 4);
644:       ctx.strokeStyle = 'rgba(230,190,110,.25)';
645:       ctx.lineWidth = 1;
