108: /** A wobbly organic polygon from a center, radius and seed. */
109: export function blob(ctx, x, y, rx, ry, rand, points = 9, jag = .18) {
110:   const pts = [];
111:   for (let i = 0; i < points; i++) {
112:     const a = (i / points) * TAU;
113:     const j = 1 + (rand() - .5) * jag * 2;
114:     pts.push({ x: x + Math.cos(a) * rx * j, y: y + Math.sin(a) * ry * j });
115:   }
116:   ctx.beginPath();
117:   ctx.moveTo(pts[0].x, pts[0].y);
118:   for (let i = 1; i < pts.length; i++) {
119:     const p = pts[i], n = pts[(i + 1) % pts.length];
120:     ctx.quadraticCurveTo(p.x, p.y, (p.x + n.x) / 2, (p.y + n.y) / 2);
121:   }
122:   ctx.closePath();
123:   return pts;
124: }

