input.newString:
function buildLedgeShape(p, rand) {
  const L = p.len, T = p.t;
  const pts = [];
  const topN = Math.max(3, Math.round(L / 90));
  for (let i = 0; i <= topN; i++) {
    const x = -L / 2 + (i / topN) * L;
    const y = -T / 2 + (i === 0 || i === topN ? 0 : (rand() - .5) * 1.2);
    pts.push({ x, y });
  }
  const inset = Math.min(T * .26, 28);
  pts.push({ x: L / 2 - inset * .35, y: -T / 2 + T * .24 });
  pts.push({ x: L / 2 - inset, y: T / 2 - T * .12 });
  // fewer, larger chunks: a rock shelf, not a torn sheet
  const botN = Math.max(3, Math.round(L / 120));
  for (let i = botN; i >= 0; i--) {
    const u = i / botN;
    const x = -L / 2 + (.04 + u * .92) * L;
    const mid = 1 - Math.abs(u - .5) * 2;
    const extra = T * (.05 + rand() * .5) * (.45 + mid * .75);
    const ledge = (rand() > .55 ? 10 + rand() * 26 : 0);
    pts.push({ x: x - L / botN * .22, y: T / 2 + extra * .45 });
    pts.push({ x, y: T / 2 + extra + ledge });
    pts.push({ x: x + L / botN * .22, y: T / 2 + extra * .5 });
  }
  pts.push({ x: -L / 2 + inset, y: T / 2 - T * .12 });
  pts.push({ x: -L / 2 + inset * .35, y: -T / 2 + T * .24 });
  return pts;
}

