import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.addInitScript(() => {
  const E = CanvasRenderingContext2D.prototype.ellipse;
  CanvasRenderingContext2D.prototype.ellipse = function (x, y, rx, ry, ...rest) {
    if (rx > 60 || ry > 60) {
      const st = new Error().stack.split('\n').slice(2, 5).join(' | ');
      window.__bigEllipses ||= [];
      if (window.__bigEllipses.length < 40) window.__bigEllipses.push({ x, y, rx, ry, st });
    }
    return E.call(this, x, y, rx, ry, ...rest);
  };
  const A = CanvasRenderingContext2D.prototype.arc;
  CanvasRenderingContext2D.prototype.arc = function (x, y, r, ...rest) {
    if (r > 60) {
      const st = new Error().stack.split('\n').slice(2, 5).join(' | ');
      window.__bigArcs ||= [];
      if (window.__bigArcs.length < 40) window.__bigArcs.push({ x, y, r, st });
    }
    return A.call(this, x, y, r, ...rest);
  };
});
await page.goto('http://localhost:3002/?debug=1&cp=0', { waitUntil: 'load', timeout: 45000 });
await page.waitForFunction(() => document.fonts.status === 'loaded');
await page.waitForTimeout(700);
const btn = await page.$('#begin-btn');
if (btn) { await btn.click(); await page.waitForTimeout(1400); }
const data = await page.evaluate(() => ({ ellipses: window.__bigEllipses, arcs: window.__bigArcs, cam: window.__HP.camera, mouse: window.__HP.mouse }));
console.log(JSON.stringify(data, null, 1));
await browser.close();

