import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('http://localhost:3002/?debug=1&cp=0', { waitUntil: 'load', timeout: 45000 });
await page.waitForFunction(() => document.fonts.status === 'loaded');
await page.waitForTimeout(700);
const btn = await page.$('#begin-btn');
if (btn) { await btn.click(); await page.waitForTimeout(1000); }
const method = process.argv[2];
const out = process.argv[3] || '/tmp/opencode/shots/dis.png';
const expr = process.argv[4];
await page.evaluate(({ method, expr }) => {
  if (method) window.__HP.renderer[method] = function () {};
  if (expr) eval(expr);
}, { method, expr });
await page.waitForTimeout(400);
await page.screenshot({ path: out, timeout: 30000 });
console.log('saved', out, method, expr);
await browser.close();
